import type { BankQuestion } from "@/lib/bank";

/** Cloze Test, Para Jumbles and Sentence Completion (English Language): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "eng-cloze-rearrangement-1", "question": "Fill in the blank: The doctor advised him to ___ smoking if he wanted his cough to improve.", "options": ["give up", "give off", "give out", "give in"], "answer": 0, "explanation": "'Give up' means to stop a habit. 'Give in' means to surrender, 'give off' means to emit (smoke, smell) and 'give out' means to distribute or to stop working.", "difficulty": "easy", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-2", "question": "Fill in the blank: Despite the heavy rain, the match was not ___; the players returned to the field after a short break.", "options": ["abandoned", "admired", "started", "celebrated"], "answer": 0, "explanation": "'Despite the heavy rain' together with play resuming after a break means the match was not called off, i.e. not abandoned. The other words do not fit the contrast.", "difficulty": "easy", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-3", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Then add the tea leaves and let them simmer for a minute. Q: First, boil a cup of water in a pan. R: Finally, strain the tea into a cup and add sugar to taste. S: Add milk and bring the mixture to a boil again.", "options": ["PQSR", "QPRS", "QPSR", "QSPR"], "answer": 2, "explanation": "The markers fix the order: 'First' (Q), 'Then' add leaves (P), add milk and boil again (S), 'Finally' strain (R), giving QPSR.", "difficulty": "easy", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-4", "question": "Fill in the blank: Not only ___ the examination, but she also topped the district.", "options": ["passed she", "she did pass", "she passed", "did she pass"], "answer": 3, "explanation": "When a sentence begins with 'Not only', the auxiliary comes before the subject (inversion): 'Not only did she pass…'. Without the auxiliary 'did' the inversion is incomplete.", "difficulty": "easy", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-5", "question": "Fill in the blank: The river, swollen by a week of rain, had ___ its banks and flooded the low-lying fields.", "options": ["overtaken", "overflowed", "overlooked", "overcome"], "answer": 1, "explanation": "A river that floods the fields has risen above its banks, so it 'overflowed' them. 'Overlooked' means ignored or had a view of, and 'overtaken' means passed.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-6","question":"Fill in the blanks: The scientist's theory was at first ___ by her colleagues, but later experiments ___ it completely.","options":["ridiculed, discredited","praised, confirmed","ignored, abandoned","ridiculed, vindicated"],"answer":3,"explanation":"'But' signals a reversal. A theory that was first mocked (ridiculed) was later proved right (vindicated). 'Ridiculed, discredited' and 'praised, confirmed' keep both halves in the same direction, so there is no contrast.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-7", "question": "The first sentence is given. Arrange P, Q, R and S to complete the paragraph. 1: Alexander Fleming returned from a holiday in September 1928. P: He noticed that one dish had been contaminated by a mould. Q: Around the mould, the bacteria had been destroyed. R: On his bench lay a stack of culture dishes of bacteria that he had left behind. S: This chance observation led to the discovery of penicillin.", "options": ["PQRS", "RPQS", "RQPS", "PRQS"], "answer": 1, "explanation": "R introduces the dishes, P says one dish had mould, Q tells what happened around 'the mould', and S sums it up as 'this chance observation'. So the order is RPQS.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-8", "question": "Fill in the blank: The old bridge had been declared unsafe; ___, hundreds of people continued to cross it every day.", "options": ["consequently", "moreover", "nevertheless", "therefore"], "answer": 2, "explanation": "People kept crossing in spite of the warning, which is a contrast, so 'nevertheless' fits. 'Therefore' and 'consequently' signal a result, and 'moreover' adds a similar point.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-9", "question": "Fill in the blank: After months of negotiation, the two companies finally ___ an agreement.", "options": ["attained to", "arrived", "came", "reached"], "answer": 3, "explanation": "'Reach an agreement' is the standard collocation. 'Arrived' and 'came' would need 'at', and 'attain' takes no preposition.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-10", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: As a result, its leaves wilt during the hottest part of the day. Q: A plant loses water through tiny pores in its leaves. R: In very dry weather, it cannot replace this water fast enough through its roots. S: Many desert plants avoid this problem by opening their pores only at night.", "options": ["QRPS", "RQPS", "SQRP", "QPRS"], "answer": 0, "explanation": "Q states the basic fact, R gives the difficulty ('this water'), P gives the result ('As a result… wilt'), and S offers the desert plants' solution to 'this problem'. So the order is QRPS.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-11", "question": "Fill in the blanks: He was accused ___ stealing the jewels, but the court later acquitted him ___ all charges.", "options": ["for, from", "of, from", "of, of", "with, of"], "answer": 2, "explanation": "One is 'accused of' a crime and 'acquitted of' a charge. 'Acquitted from' is a common error.", "difficulty": "moderate", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-12","question":"Fill in the blank: His explanation was so ___ that even the experts struggled to follow it.","options":["convoluted","succinct","candid","perspicuous"],"answer":0,"explanation":"If even experts could not follow it, the explanation was complicated and twisting, i.e. convoluted. 'Perspicuous' (clearly expressed) and 'succinct' (brief) point the opposite way.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-13", "question": "Choose the set of words that fills the numbered blanks correctly: Good habits are not built in a day. They are the (1) ___ of small actions repeated until they become (2) ___. The difficulty is that the rewards of a good habit are usually (3) ___, while its costs are felt at once.", "options": ["result, difficult, delayed", "result, automatic, delayed", "result, automatic, immediate", "cause, automatic, immediate"], "answer": 1, "explanation": "Habits result from repeated actions until they become automatic. 'While its costs are felt at once' needs a contrast for blank 3, so 'delayed', not 'immediate'.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-14", "question": "Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: Volcanoes are not only destroyers. P: Over centuries, these minerals break down into some of the most fertile soils on earth. Q: The lava and ash they throw out are rich in minerals. R: That is why farmers often return to the slopes of a volcano soon after an eruption. S: Crops such as coffee and grapes thrive in them. 6: Fertility, it seems, can outweigh fear.", "options": ["QPRS", "QPSR", "QSPR", "PQSR"], "answer": 1, "explanation": "Q introduces minerals, P refers to 'these minerals' becoming soils, S says crops thrive 'in them' (the soils), and R draws the conclusion ('That is why farmers return'), which leads to sentence 6. So the order is QPSR.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-15", "question": "Fill in the blanks: Far from ___ the dispute, the minister's remarks only ___ it.", "options": ["inflaming, intensified", "ignoring, forgot", "settling, inflamed", "resolving, settled"], "answer": 2, "explanation": "'Far from X, only Y' needs Y to be the opposite of X. The remarks did not settle the dispute but made it worse (inflamed it). 'Inflaming, intensified' has no contrast.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-16", "question": "Fill in the blank: The meeting had to be ___ because the chairperson fell ill; it will now be held next Friday.", "options": ["called off", "called up", "put off", "put out"], "answer": 2, "explanation": "Since the meeting will still be held next Friday, it was postponed ('put off'). 'Called off' means cancelled, which clashes with the new date.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-17", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: But when everyone in a stadium stands, nobody sees any better, and everyone is less comfortable. Q: At a football match, a spectator who stands up gets a better view. R: What makes sense for one person can be foolish for all. S: So the people behind him stand up too, and soon the whole stadium is on its feet.", "options": ["QPSR", "QSPR", "PQSR", "SQPR"], "answer": 1, "explanation": "Q gives the individual's gain, S the chain reaction ('So the people behind him…'), P the result for everyone ('But when everyone stands'), and R the general lesson. So the order is QSPR.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-18", "question": "Fill in the blank: It is high time the government ___ steps to clean the river.", "options": ["took", "takes", "has taken", "will take"], "answer": 0, "explanation": "'It is high time' is followed by the past subjunctive (simple past form) to show that the action is overdue: 'It is high time the government took steps.'", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-19", "question": "Fill in the blank: The opposition ___ a motion of no confidence against the government in the Lok Sabha.", "options": ["moved", "made up", "did", "gave"], "answer": 0, "explanation": "In parliamentary usage a motion is 'moved' (or tabled). 'Did', 'made up' and 'gave' are not used with 'motion'.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-20", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Within a few centuries it had spread through Persia to the Arab world. Q: Chess is believed to have originated in India around the sixth century as chaturanga. R: From there, traders and scholars carried it into Europe. S: There, its rules were changed in the fifteenth century, making the queen the most powerful piece.", "options": ["QPRS", "PQRS", "QRPS", "QPSR"], "answer": 0, "explanation": "Q names the origin, P tells how 'it' spread to the Arab world, R continues 'from there' into Europe, and S says 'there' (in Europe) the rules changed. So the order is QPRS.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-21", "question": "Fill in the blank: Walk carefully on the icy path lest you ___.", "options": ["should slip", "slipped", "will slip", "would not slip"], "answer": 0, "explanation": "'Lest' already means 'so that… not', so it takes 'should' + verb (or the bare verb), never 'will' or a negative. 'Lest you would not slip' is a double negative.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-22", "question": "Fill in the blank: Unlike his brother, who spent every rupee he earned, Arun was extremely ___, saving even the smallest coins for the future.", "options": ["prodigal", "generous", "reckless", "frugal"], "answer": 3, "explanation": "'Unlike' sets Arun against a spendthrift brother, and he saves every coin, so he is frugal (thrifty). 'Prodigal' means wasteful, which describes the brother.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-23", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: However, the same feature makes it difficult to dispose of. Q: Plastic is valued because it is light, cheap and extremely durable. R: Some types take hundreds of years to break down in a landfill. S: Recycling helps, but only a small fraction of plastic is ever recycled.", "options": ["QPSR", "PQRS", "QPRS", "QRPS"], "answer": 2, "explanation": "Q names durability, P turns it around with 'However, the same feature…', R gives the evidence (hundreds of years to break down), and S offers a partial remedy. So the order is QPRS.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-24", "question": "Fill in the blanks: The witness's account was ___ with the physical evidence, so the jury found it ___.", "options": ["inconsistent, convincing", "consistent, credible", "consistent, doubtful", "at odds, reliable"], "answer": 1, "explanation": "'So' signals a result. Testimony that matches the evidence (consistent) would be found believable (credible). The other pairs pull in opposite directions.", "difficulty": "hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-25", "question": "Choose the set of words that fills the numbered blanks correctly: The old fort, once the (1) ___ of a powerful kingdom, now lies in (2) ___. Its walls, which had (3) ___ countless sieges, are crumbling under nothing more (4) ___ than rain and neglect.", "options": ["seat, ruins, withheld, dramatic", "sight, ruins, withstood, dramatic", "seat, ruins, withstood, dramatically", "seat, ruins, withstood, dramatic"], "answer": 3, "explanation": "A capital is the 'seat' of a kingdom (not 'sight'). Walls 'withstood' sieges ('withheld' means held back). 'Nothing more dramatic than' needs the adjective 'dramatic', not the adverb.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-26", "question": "Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: The idea of a minimum wage seems simple. P: Critics reply that if the wage is set too high, employers will hire fewer workers. Q: Supporters argue that it protects workers who have little power to bargain. R: Studies of actual increases, however, have found smaller job losses than critics predicted, though the effect varies with the region and the size of the rise. S: The truth, as usual, lies in the details. 6: Policymakers must therefore look closely at local conditions before setting the wage.", "options": ["PQRS", "QRPS", "QPRS", "QPSR"], "answer": 2, "explanation": "'Critics reply' (P) needs a claim to reply to, so the supporters' argument (Q) comes first. R answers the critics with evidence, and S ('the truth lies in the details') leads to 6. So the order is QPRS.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-27", "question": "Fill in the blank: Rather than wait for the press to uncover its errors, the new chief executive decided to ___ and admit the company's mistakes publicly.", "options": ["let sleeping dogs lie", "pass the buck", "bite the bullet", "beat around the bush"], "answer": 2, "explanation": "'Bite the bullet' means to face something unpleasant bravely, which fits openly admitting mistakes. 'Let sleeping dogs lie' (avoid stirring up trouble) and 'pass the buck' (shift blame) mean the opposite.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-28", "question": "Which single word can fill BOTH blanks correctly? (i) A fresh guard will ___ the night watchman at midnight. (ii) This medicine should ___ your headache within an hour.", "options": ["ease", "cure", "replace", "relieve"], "answer": 3, "explanation": "'Relieve' means both to take over a duty from someone (i) and to lessen pain (ii). 'Ease' fits only (ii), and 'replace' fits only (i).", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-29", "question": "In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Honeybees pollinate a large share of the crops humans eat. Q: In recent years, beekeepers in many countries have reported unusual losses of colonies. R: Suspected causes include pesticides, parasitic mites and the loss of wild flowers. S: Honey has been used as a medicine since ancient times.", "options": ["P", "S", "R", "Q"], "answer": 1, "explanation": "P, Q and R form a paragraph about the decline of bee colonies and why it matters for crops. S, on honey as an ancient medicine, is off the topic.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-30", "question": "Fill in the blanks: Although the drug worked well in laboratory tests, its ___ side effects made doctors ___ to prescribe it.", "options": ["negligible, hesitant", "severe, eager", "severe, reluctant", "mild, reluctant"], "answer": 2, "explanation": "'Although' contrasts good test results with a drawback, so the side effects were severe and doctors were reluctant. Mild or negligible side effects give no reason for reluctance.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-31","question":"Fill in the blank: Had I known about the traffic jam on the highway, I ___ home much earlier.","options":["would leave","will have left","would have been left","would have left"],"answer":3,"explanation":"'Had I known' is an inverted third conditional (= If I had known), about an unreal past. The main clause therefore takes active 'would have' + past participle; 'would have been left' is passive and changes the meaning.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-32", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Strangely, the effect can appear even when patients are told that the pill contains no medicine. Q: In a typical drug trial, some patients receive the real medicine and others a sugar pill. R: Many in the second group nevertheless report feeling better, a phenomenon known as the placebo effect. S: This suggests that the ritual of treatment, and not only belief in it, plays a part in healing.", "options": ["QRPS", "RQPS", "QPRS", "QRSP"], "answer": 0, "explanation": "Q sets up the trial, R names the placebo effect in 'the second group', P adds the surprising twist about 'the effect', and S draws the conclusion. S must follow P, because the point about belief depends on patients knowing the pill is inert. So the order is QRPS.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-33", "question": "Fill in the blanks: The critic's review was ___: it praised the actors lavishly while ___ the director for a muddled plot.", "options": ["glowing, faulting", "mixed, faulting", "scathing, praising", "mixed, commending"], "answer": 1, "explanation": "Lavish praise for the actors plus blame for the director makes a mixed review. 'Glowing' ignores the criticism, and 'commending' turns the criticism into praise.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-34","question":"Choose the sentence that best fills the blank in the paragraph: Many people believe that multitasking makes them more productive. Research suggests otherwise. ___ Each switch carries a small cost in time and attention, and these costs add up over a day.","options":["Productivity matters to every organisation.","Multitasking became popular after computers were invented.","Some people can sing and dance at the same time.","Multitasking is mostly rapid switching between tasks."],"answer":3,"explanation":"The next sentence talks of 'each switch', so the missing sentence must first describe multitasking as switching between tasks. The other options do not set up 'switch'.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-35", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: By the time the firefighters arrived, the flames had reached the second floor. Q: A short circuit in the ground-floor kitchen started the fire just after midnight. R: They found, to their relief, that the alarm had already emptied the building. S: Within minutes, smoke had filled the stairwell and set off the alarm.", "options": ["QPSR", "QSPR", "QSRP", "SQPR"], "answer": 1, "explanation": "Q is the start, S follows 'within minutes', and P brings in the firefighters. R's 'They' refers to the firefighters, so R must come right after P. So the order is QSPR.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-36", "question": "Fill in the blank: The professor's lectures were notoriously ___; students struggled to stay awake through his monotonous delivery.", "options": ["soporific", "esoteric", "vociferous", "stimulating"], "answer": 0, "explanation": "'Soporific' means sleep-inducing, which matches students struggling to stay awake. 'Esoteric' (understood by few) is tempting, but the clue is sleepiness, not obscurity.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-37", "question": "Choose the set of words that fills the numbered blanks correctly: The talks reached an (1) ___ when neither side would yield; a mediator was called in to (2) ___ the deadlock, and after a week a (3) ___ was reached.", "options": ["climax, break, compromise", "impasse, brake, compromise", "impasse, break, compromission", "impasse, break, compromise"], "answer": 3, "explanation": "A deadlock where neither side yields is an 'impasse', not a 'climax'. One 'breaks' a deadlock ('brake' is a homophone meaning to slow down), and the outcome is a 'compromise'.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-38", "question": "Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: It was not until 1953 that its structure, a double helix, was described. Q: DNA was first isolated by a Swiss chemist in 1869. R: For decades afterwards, most scientists believed that proteins, not DNA, carried hereditary information. S: Experiments in the 1940s and early 1950s gradually showed that DNA was the genetic material.", "options": ["QPRS", "QSRP", "RQSP", "QRSP"], "answer": 3, "explanation": "The dates and links set the order: 1869 isolation (Q), 'for decades afterwards' proteins were favoured (R), experiments in the 1940s–50s (S), and 1953 double helix (P). So the order is QRSP.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-39", "question": "Fill in the blank: The more you practise public speaking, ___ you will become.", "options": ["the more confident", "more confident", "the most confident", "the confident"], "answer": 0, "explanation": "The comparative correlative needs 'the + comparative' in both halves: 'The more…, the more confident…'. Dropping 'the' or using the superlative is wrong.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id": "eng-cloze-rearrangement-40", "question": "In the paragraph below, which highlighted word is used incorrectly? The museum's new wing, which (A) houses ancient coins, was (B) inaugurated last week. Visitors (C) complemented the curators on the elegant displays, and many said the exhibits were (D) well worth the visit.", "options": ["complemented", "inaugurated", "houses", "well worth"], "answer": 0, "explanation": "To praise someone is to 'compliment' them; 'complement' means to complete or go well with. The other words are used correctly.", "difficulty": "very-hard", "source": "SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-41","question":"Fill in the blank: The firefighters worked through the night to ___ the blaze before it reached the village.","options":["contend","content","contain","contact"],"answer":2,"explanation":"To 'contain' a fire is to keep it from spreading. 'Contend' means to struggle or argue, and 'content' and 'contact' do not fit.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-42","question":"Fill in the blank: She was so ___ in her novel that she did not hear the doorbell ring.","options":["engrossed","engraved","enthroned","enlarged"],"answer":0,"explanation":"'Engrossed in' means completely absorbed in, which explains why she missed the doorbell. 'Engraved' and 'enthroned' are look-alike traps that make no sense with a novel.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-43","question":"Fill in the blank: The revised timetable will take ___ from the first of April.","options":["affect","effect","affection","efficient"],"answer":1,"explanation":"'Take effect' means to come into operation. 'Affect' is a verb meaning to influence and cannot follow 'take' here.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-44","question":"Fill in the blank: Please ___ me know if you need any help with the luggage.","options":["permit","make","allow","let"],"answer":3,"explanation":"'Let me know' is the natural expression and takes the bare infinitive. 'Allow' and 'permit' would need 'to' (allow me to know) and sound unnatural here.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-45","question":"Fill in the blank: He apologised ___ arriving late to the meeting.","options":["of","for","with","on"],"answer":1,"explanation":"We apologise TO a person FOR something we have done: 'apologised for arriving late'.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-46","question":"Fill in the blank: It had not rained for months; ___, the crops had withered in the fields.","options":["meanwhile","nevertheless","however","consequently"],"answer":3,"explanation":"The withered crops are a result of the drought, so a cause-and-effect connector, 'consequently', is needed. 'Nevertheless' and 'however' signal contrast.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-47","question":"Fill in the blank: The child was ___ of the dark and refused to sleep alone.","options":["frightening","scary","afraid","horrible"],"answer":2,"explanation":"A person is 'afraid of' something. 'Scary' and 'frightening' describe the thing that causes fear, not the person who feels it.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-48","question":"Fill in the blank: The teacher asked the students to ___ their answers carefully before handing in the paper.","options":["revise","revive","reverse","revoke"],"answer":0,"explanation":"To 'revise' answers is to read through and correct them. 'Revive' means to bring back to life, and 'revoke' means to cancel.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-49","question":"Fill in the blank: Our flight was delayed ___ thick fog over the airport.","options":["owing to","in spite of","instead of","apart from"],"answer":0,"explanation":"'Owing to' gives the cause of the delay. 'In spite of' would imply the flight was delayed although there was fog, which makes no sense.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-50","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Next, place the sapling in the pit and fill it with soil. Q: First, dig a pit about two feet deep. R: Finally, water the plant regularly until it takes root. S: Then press the soil firmly around the stem.","options":["PQSR","QSPR","QPSR","QPRS"],"answer":2,"explanation":"The sequence words decide the order: First (Q), Next (P), Then (S), Finally (R).","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-51","question":"Fill in the blank: Despite being the youngest player in the team, she showed remarkable ___ under pressure.","options":["composition","composure","compost","compulsion"],"answer":1,"explanation":"'Composure' means calmness and self-control, which is what one shows under pressure. The other words only look similar.","difficulty":"easy","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-52","question":"Fill in the blanks: The committee ___ the proposal because it was ___ expensive.","options":["welcomed, prohibitively","accepted, reasonably","rejected, moderately","rejected, prohibitively"],"answer":3,"explanation":"'Because it was prohibitively (so much as to rule it out) expensive' is a natural reason for rejecting it. Welcoming a prohibitively expensive plan is illogical, and 'moderately expensive' is too weak a reason.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-53","question":"Fill in the blank: The minister's speech was full of ___ promises that nobody expected him to keep.","options":["hollow","solid","hallowed","holy"],"answer":0,"explanation":"'Hollow promises' are empty ones, matching 'nobody expected him to keep'. 'Hallowed' (sacred) is a look-alike trap.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-54","question":"Fill in the blank: The company had to ___ its plans for expansion when sales fell sharply.","options":["shell","shelve","shelter","shove"],"answer":1,"explanation":"To 'shelve' a plan is to postpone or abandon it for the time being, the natural response to falling sales.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-55","question":"Fill in the blank: Being a man of few words, he gave a ___ reply to every question.","options":["tedious","verbose","tense","terse"],"answer":3,"explanation":"A man of few words gives short, abrupt — terse — replies. 'Verbose' (wordy) is the opposite.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-56","question":"Fill in the blank: The plan looked perfect on paper. ___, it failed miserably when it was put into practice.","options":["Similarly","Therefore","In reality","Consequently"],"answer":2,"explanation":"The second sentence contrasts with the first, so 'In reality' fits. 'Therefore', 'consequently' and 'similarly' all continue in the same direction instead of turning against 'perfect on paper'.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-57","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: She was told that she needed proof of address to get one. Q: Meena wanted to borrow books from the city library. R: So she went home, fetched her electricity bill and returned the same afternoon. S: At the counter she asked for a membership card.","options":["SQPR","QPSR","QSPR","QSRP"],"answer":2,"explanation":"Q introduces Meena and her aim; S – she asks for a card; P – 'one' refers to the card and she is told what is needed; R – 'So' she fetches the proof.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-58","question":"The first sentence is given. Arrange P, Q, R and S to complete the paragraph. 1: The monsoon is the lifeline of Indian agriculture. P: When the rains arrive late, sowing has to be postponed. Q: Nearly half of the country's farmland depends on rain rather than on irrigation. R: A shorter season, in turn, means smaller harvests. S: And postponed sowing leaves the crop less time to grow before the weather turns.","options":["QSPR","QPRS","PQSR","QPSR"],"answer":3,"explanation":"Q explains why the monsoon is a lifeline; P – late rains postpone sowing; S – 'postponed sowing' leaves less time; R – 'a shorter season' therefore reduces harvests.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-59","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Mangroves grow along tropical coastlines in salty water. Q: Their tangled roots slow down waves and reduce damage from storms. R: They also provide breeding grounds for many species of fish. S: Coconut oil is widely used in South Indian cooking.","options":["S","P","Q","R"],"answer":0,"explanation":"P, Q and R describe mangroves and their benefits. S, about cooking oil, has nothing to do with the topic.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-60","question":"Choose the most suitable ending: Although the medicine was expensive, ___","options":["it was therefore very costly.","the family bought it at once.","nobody could afford to buy it.","its price was very high indeed."],"answer":1,"explanation":"'Although' needs a contrasting clause: despite the cost, the family bought it. The other endings merely repeat or follow from 'expensive', so there is no contrast.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-61","question":"Fill in the blank: The thief managed to ___ the police for three days before he was finally caught.","options":["delude","allude","elude","collude"],"answer":2,"explanation":"To 'elude' is to escape or evade. 'Allude' means to refer indirectly, 'delude' to deceive and 'collude' to conspire.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-62","question":"Fill in the blank: The two neighbours had been ___ over a narrow strip of land for years.","options":["fending","fuelling","feeding","feuding"],"answer":3,"explanation":"'Feuding' means engaged in a long, bitter quarrel. The other words look similar but do not take 'over a strip of land' in this sense.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-63","question":"Fill in the blank: Her argument did not ___ water, because the facts plainly contradicted it.","options":["hold","carry","keep","take"],"answer":0,"explanation":"An argument that 'does not hold water' is unconvincing or unsound. The idiom uses only 'hold'.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-64","question":"Fill in the blank: The government has launched a scheme to ___ poverty in rural areas.","options":["aggravate","alleviate","elevate","alienate"],"answer":1,"explanation":"To 'alleviate' is to lessen or relieve, which is the aim of an anti-poverty scheme. 'Aggravate' means to make worse.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-65","question":"Choose the set of words that fills the numbered blanks correctly: Sleep is not a luxury but a (1) ___. During sleep the brain (2) ___ the day's memories, and a person who is (3) ___ of rest for long periods finds it hard to concentrate.","options":["necessity, consolidates, deprived","necessity, consolidates, depraved","privilege, consolidates, deprived","necessity, scatters, deprived"],"answer":0,"explanation":"'Not a luxury but a necessity' is the natural contrast; the brain consolidates (strengthens) memories; a person 'deprived of' rest suffers. 'Depraved' (morally corrupt) is a sound-alike trap.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-66","question":"Fill in the blank: The judge's verdict was completely ___; nobody could point to any bias in it.","options":["impractical","partial","imperial","impartial"],"answer":3,"explanation":"'Impartial' means unbiased, as the second clause confirms. 'Partial' means the opposite.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-67","question":"Fill in the blank: The rescue team found the missing climbers ___ but exhausted.","options":["living","live","alive","lively"],"answer":2,"explanation":"'Alive' is used after a verb or object ('found them alive'). 'Live' is used before a noun ('live wires'), and 'lively' means full of energy, which contradicts 'exhausted'.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-68","question":"Fill in the blanks: The scientist was ___ by the results, which ___ everything she had hoped to prove.","options":["delighted, contradicted","delighted, confirmed","dismayed, confirmed","indifferent, surpassed"],"answer":1,"explanation":"Results that confirm what she hoped to prove would delight her. Being dismayed by confirmation, or delighted by contradiction, is illogical.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-69","question":"Fill in the blank: He is not only a gifted singer ___ a talented painter.","options":["and also","as well","but also","but too"],"answer":2,"explanation":"'Not only ... but also' is a fixed correlative pair, so the second half must open with 'but also'. 'And also' and 'as well' do not pair with 'not only', and 'but too' is not idiomatic.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-70","question":"Fill in the blank: The old woman ___ her entire savings to the orphanage in her will.","options":["beseeched","bereaved","bewildered","bequeathed"],"answer":3,"explanation":"To 'bequeath' is to leave property to someone by a will. 'Bereaved' means having lost a relative and 'beseeched' means begged; they only look alike.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-71","question":"Fill in the blank: The car broke ___ on the highway, so we had to call a mechanic.","options":["down","out","away","off"],"answer":0,"explanation":"A vehicle that stops working 'breaks down'. 'Break out' is used for wars or fires, 'break away' for leaving a group, and 'break off' for ending talks or snapping a piece.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-72","question":"Fill in the blank: After the surgery, the doctor ___ him against eating oily food.","options":["caused","cautioned","cauterised","captured"],"answer":1,"explanation":"To 'caution someone against' something is to warn him not to do it. 'Cauterised' (burnt to seal a wound) is a look-alike trap.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-73","question":"Fill in the blank: The audience ___ spellbound throughout the performance.","options":["seated","set","seat","sat"],"answer":3,"explanation":"'Sat' (past of 'sit') is the intransitive verb needed. 'Set' needs an object, 'seat' is a noun or transitive verb, and 'seated' would need 'were'.","difficulty":"moderate","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-74","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: Plastic was once hailed as a wonder material. P: Cheap, light and durable, it quickly replaced glass, metal and paper in thousands of products. Q: Yet the very durability that made it attractive has become its biggest drawback. R: A bottle thrown away today may still be lying in a landfill centuries from now. S: Recycling helps, but only a small fraction of plastic is ever recycled. 6: The wonder material, it seems, has outstayed its welcome.","options":["PQRS","PQSR","QPRS","PRQS"],"answer":0,"explanation":"P explains why it was a 'wonder'; Q turns ('Yet') to its drawback, durability; R illustrates that durability; S considers the partial remedy, leading to the conclusion in 6.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-75","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: The printing press made books far cheaper to produce. Q: As a result, ideas could spread well beyond the small circle of scholars. R: Gutenberg had trained as a goldsmith before he turned to printing. S: Literacy rose steadily as more people gained access to the written word.","options":["Q","P","R","S"],"answer":2,"explanation":"P, Q and S trace the effects of cheap printing on the spread of ideas and literacy. R, about Gutenberg's earlier trade, is biographical and breaks the chain of cause and effect.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-76","question":"Fill in the blanks: The novel's ending is deliberately ___, leaving readers to ___ for themselves whether the hero survives.","options":["conclusive, decide","ambiguous, decide","ambiguous, forget","obvious, wonder"],"answer":1,"explanation":"If readers must decide for themselves, the ending must be ambiguous (open to more than one reading). A conclusive or obvious ending leaves nothing to decide.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-77","question":"Fill in the blank: His ___ attitude towards his studies — he never opened a book until the night before the exam — cost him the scholarship.","options":["cavernous","cautious","diligent","cavalier"],"answer":3,"explanation":"'Cavalier' means showing arrogant or careless disregard, as the example in dashes shows. 'Diligent' and 'cautious' are opposites; 'cavernous' only looks similar.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-78","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: Honey never spoils if it is stored properly. P: Honey contains very little water and is highly acidic. Q: Moreover, bees add an enzyme that produces small amounts of hydrogen peroxide, a mild antiseptic. R: The reason lies in its chemistry. S: This makes it hard for bacteria to survive in it. 6: Archaeologists have even found edible honey in ancient Egyptian tombs.","options":["RPSQ","RSPQ","PSRQ","RPQS"],"answer":0,"explanation":"R announces the explanation; P gives the chemistry; S ('This') states its effect on bacteria; Q ('Moreover') adds a second reason before the example in 6.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-79","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Their slogan, 'Stop the child murder', drew wide public sympathy. Q: Responding to the pressure, the city built separate cycle lanes and slowed down motor traffic. R: The result was a city in which a majority of trips came to be made by bicycle. S: In the 1970s, after a spate of road deaths, citizens of Amsterdam began protesting against the dominance of cars.","options":["SQPR","SPQR","PSQR","SPRQ"],"answer":1,"explanation":"S sets the scene; P ('Their slogan') refers to the protesters; Q responds to 'the pressure'; R gives 'the result'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-80","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: The idea of zero as a number is one of India's great gifts to mathematics. P: Brahmagupta, in the seventh century, even laid down rules for adding and subtracting it. Q: From India the concept travelled through the Arab world to Europe. R: Earlier civilisations used only a blank space or a placeholder to show an empty position. S: Indian mathematicians, however, treated zero as a number in its own right. 6: Without it, modern computing would be unthinkable.","options":["RPSQ","SRPQ","RSPQ","RSQP"],"answer":2,"explanation":"R describes the earlier practice; S contrasts it with 'however'; P adds the detail ('even laid down rules'); Q traces its spread, leading to 6.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-81","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: Priya walked into the interview feeling well prepared. P: She had rehearsed answers to every technical question she could imagine. Q: Instead, he began by asking about her hobbies. R: But the interviewer did not ask a single one of them. S: Caught off guard, she hesitated, then spoke about her love of trekking. 6: Months later, he told her it was that answer which got her the job.","options":["PRSQ","PQRS","RPQS","PRQS"],"answer":3,"explanation":"P – her preparation; R – 'But' none of those questions came; Q – 'Instead' he asked about hobbies; S – her reaction, which 'that answer' in 6 refers to.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-82","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: The monks dried and boiled the berries, producing a drink that kept them awake through long night prayers. Q: He tried the berries himself and felt the same burst of energy. R: News of his discovery soon reached a nearby monastery. S: A popular legend says that a goatherd named Kaldi noticed his goats became lively after eating certain red berries.","options":["SQRP","SRQP","QSRP","SQPR"],"answer":0,"explanation":"S introduces the legend; Q – 'He' (Kaldi) tries the berries; R – the news reaches the monastery; P – the monks make the drink.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-83","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Cities are often several degrees warmer than the countryside around them. Q: Planting trees and painting roofs white are two simple ways of reducing this effect. R: Add to this the heat from vehicles and air-conditioners, and the city becomes an 'island' of warmth. S: Concrete and asphalt absorb sunlight during the day and release the heat slowly at night.","options":["SPRQ","PRSQ","PSRQ","PSQR"],"answer":2,"explanation":"P states the phenomenon; S gives the first cause; R ('Add to this') adds more causes and names the 'island'; Q offers remedies for 'this effect'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-84","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: He noticed that milkmaids who had caught cowpox seemed never to catch smallpox. Q: The boy did not fall ill, and the age of vaccination had begun. R: To test his idea, he infected a boy with cowpox and later exposed him to smallpox. S: Edward Jenner was a country doctor in England in the late eighteenth century.","options":["SRPQ","SPRQ","PSRQ","SPQR"],"answer":1,"explanation":"S introduces Jenner; P – his observation; R – 'To test his idea'; Q – the outcome.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-85","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: This is the power of compounding: returns go on to earn returns of their own. Q: In the first year, the gap between them is barely noticeable. R: Two friends each invest the same sum, one at 8% a year and the other at 10%. S: Over thirty years, though, the difference becomes enormous.","options":["RQPS","RSQP","QRSP","RQSP"],"answer":3,"explanation":"R sets up the comparison; Q – early years ('the gap between them'); S – 'though' contrasts with the long run; P names the principle behind it.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-86","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: One group spent ten minutes writing about their fears; the other sat quietly. Q: In one experiment, students about to take a test were split into two groups. R: Psychologists suggest that putting worries on paper frees up mental space for the task itself. S: The students who had written about their worries scored noticeably higher.","options":["PQSR","QSPR","QPSR","QPRS"],"answer":2,"explanation":"Q sets up the experiment; P describes the two groups; S gives the result; R explains it.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-87","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Glaciers in the Himalayas are retreating at an accelerating pace. Q: Millions of people downstream depend on their meltwater for drinking and irrigation. R: In the short run faster melting may swell the rivers, but once the glaciers shrink, flows will fall. S: The glaciers also attract thousands of trekkers each year, boosting local economies.","options":["P","S","Q","R"],"answer":1,"explanation":"P, Q and R concern the retreat of glaciers and its threat to water supplies. S is about the same glaciers but shifts to tourism, so it does not fit the paragraph's concern.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-88","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Vitamins are best obtained from a balanced diet rather than from tablets. Q: But their overuse has allowed bacteria to evolve resistance to many of them. R: Patients who stop a course of medicine early add to the problem. S: Antibiotics have saved millions of lives since the 1940s.","options":["S","R","Q","P"],"answer":3,"explanation":"Q, R and S build the theme of antibiotic resistance. P, on vitamins, is a different health topic.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-89","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: A child who sees parents reading is more likely to pick up books. Q: Reading aloud at bedtime builds vocabulary long before school begins. R: Libraries that run story hours for toddlers report growing membership. S: Many schools now teach computer coding from the primary classes onward.","options":["S","R","P","Q"],"answer":0,"explanation":"P, Q and R are about encouraging reading in early childhood. S, about coding classes, leaves that theme.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-90","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Millets need far less water than rice or wheat. Q: They also tolerate poor soils and high temperatures. R: Rice is the staple food in most of eastern and southern India. S: This makes them well suited to a warming, drier climate.","options":["P","Q","S","R"],"answer":3,"explanation":"P, Q and S argue that millets suit a changing climate. R mentions rice only as a food habit and adds nothing to that argument.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-91","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Working from home saves employees hours of commuting each week. Q: Many companies have also cut their spending on office space. R: Some managers, however, worry that it weakens team spirit and the mentoring of juniors. S: Video-calling apps now offer dozens of colourful virtual backgrounds.","options":["Q","R","S","P"],"answer":2,"explanation":"P, Q and R weigh the benefits and drawbacks of remote work. S is a trivial detail about software features and does not contribute.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-92","question":"Choose the set of words that fills the numbered blanks correctly: Inflation is often described as a hidden tax. When prices rise, the same amount of money buys (1) ___ goods, so savers see the real value of their deposits (2) ___. Those on fixed incomes, such as pensioners, are hit (3) ___.","options":["fewer, shrink, hardest","more, shrink, hardest","fewer, increase, hardest","fewer, shrink, least"],"answer":0,"explanation":"Rising prices mean money buys fewer goods, real savings shrink, and people whose income does not rise are hit hardest.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-93","question":"Choose the set of words that fills the numbered blanks correctly: Good writing is not about using (1) ___ words. It is about saying exactly what you mean in a way the reader can (2) ___ without effort. Clarity, not ornament, is the (3) ___ of a skilled writer.","options":["simple, follow, hallmark","long, follow, hallmark","long, ignore, hallmark","long, follow, handicap"],"answer":1,"explanation":"The passage contrasts 'long' (showy) words with clarity, the reader should 'follow' easily, and clarity is the 'hallmark' (distinguishing mark) of good writing. 'Simple' would contradict the point.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-94","question":"Choose the set of words that fills the numbered blanks correctly: The forest had once been (1) ___ with birdsong. Now, after years of logging, only a (2) ___ silence remained, broken (3) ___ by the call of a lone crow.","options":["alive, heavy, continuously","alive, heavy, occasionally","dead, heavy, occasionally","alive, light, constantly"],"answer":1,"explanation":"'Alive with birdsong' contrasts with the present 'heavy silence', which a lone crow breaks only occasionally. 'Continuously' or 'constantly' would destroy the idea of silence.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-95","question":"Choose the set of words that fills the numbered blanks correctly: Many great inventions were (1) ___ discovered. Penicillin and X-rays both emerged when researchers noticed something (2) ___ while looking for something else. Chance, however, favours only the (3) ___ mind.","options":["accidentally, expected, prepared","deliberately, unexpected, prepared","accidentally, unexpected, prepared","accidentally, unexpected, idle"],"answer":2,"explanation":"The examples are accidental discoveries of something unexpected; 'however' then qualifies the role of luck — it helps only a prepared mind.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-96","question":"Choose the set of words that fills the numbered blanks correctly: The new manager inherited a team that was (1) ___ and divided. Instead of issuing orders, she spent her first month (2) ___ to every member. By the end of the year, the team that had been the (3) ___ performer in the region was its best.","options":["demoralised, listening, best","motivated, listening, worst","demoralised, dictating, worst","demoralised, listening, worst"],"answer":3,"explanation":"'Divided' pairs with 'demoralised'; 'Instead of issuing orders' points to 'listening'; the turnaround needs 'worst' to contrast with 'best'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-97","question":"Choose the set of words that fills the numbered blanks correctly: Water scarcity is not always a matter of too little rain. Often the problem is (1) ___: leaking pipes, wasteful irrigation and polluted rivers. Fixing these may achieve more than building new dams, which are costly and (2) ___ whole villages. Managing water better can be as (3) ___ as finding more of it.","options":["mismanagement, displace, valuable","drought, displace, valuable","mismanagement, enrich, valuable","mismanagement, displace, pointless"],"answer":0,"explanation":"The examples after the colon are forms of mismanagement; large dams often displace villages; and the conclusion praises better management as equally valuable. 'Drought' contradicts 'not ... too little rain'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-98","question":"Choose the set of words that fills the numbered blanks correctly: Rumours spread faster than facts because they are usually (1) ___ and emotionally charged. Corrections, by contrast, tend to be dry and (2) ___. By the time the truth catches up, the rumour has already (3) ___ itself in people's minds.","options":["boring, complicated, lodged","sensational, complicated, lodged","sensational, exciting, lodged","sensational, complicated, erased"],"answer":1,"explanation":"Rumours spread because they are sensational; 'by contrast' corrections are dry and complicated; and a rumour that has spread has lodged (fixed) itself in minds.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-99","question":"Choose the set of words that fills the numbered blanks correctly: The tortoise did not win the race because it was fast; it won because it was (1) ___ and the hare was (2) ___. The fable reminds us that talent without (3) ___ often loses to steady effort.","options":["complacent, persistent, discipline","persistent, diligent, discipline","persistent, complacent, discipline","persistent, complacent, luck"],"answer":2,"explanation":"The tortoise kept going (persistent) while the hare was over-confident (complacent); the moral is that talent without discipline loses to steady effort. The swapped pair gives the hare's trait to the tortoise.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-100","question":"Fill in the blanks: The witness was ___ during cross-examination, ___ his earlier statement in several places.","options":["forthright, contradicting","candid, confirming","evasive, confirming","evasive, contradicting"],"answer":3,"explanation":"An evasive witness who contradicts his earlier statement fits a damaging cross-examination. A forthright witness contradicting himself, or an evasive one confirming everything, is inconsistent.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-101","question":"Fill in the blanks: Far from being ___, the new policy has ___ the very problems it was meant to solve.","options":["effective, worsened","effective, solved","harmful, worsened","ineffective, aggravated"],"answer":0,"explanation":"'Far from being X' means the opposite of X happened: far from being effective, it has worsened the problems. 'Harmful, worsened' gives no contrast, and 'far from being ineffective' would praise a policy that made things worse.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-102","question":"Fill in the blanks: The ancient manuscript was so ___ that the archivists handled it only with gloves, fearing it might ___ at a touch.","options":["valuable, harden","sturdy, crumble","fragile, flourish","fragile, crumble"],"answer":3,"explanation":"Care in handling and the fear of damage point to 'fragile' and 'crumble'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-103","question":"Fill in the blanks: The speaker's ___ remarks ___ the audience, many of whom walked out in protest.","options":["offensive, delighted","witty, alienated","offensive, alienated","soothing, provoked"],"answer":2,"explanation":"People walk out in protest when offensive remarks alienate them. 'Delighted' and 'soothing' clash with the walk-out.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-104","question":"Fill in the blanks: Although the evidence was only ___, the jury found it ___ enough to convict.","options":["conclusive, weak","circumstantial, compelling","circumstantial, irrelevant","direct, doubtful"],"answer":1,"explanation":"'Although ... only' signals a limitation followed by a contrast: indirect (circumstantial) evidence that was nevertheless compelling.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-105","question":"Fill in the blanks: The professor was known for his ___ memory; he could ___ long passages from books he had read decades earlier.","options":["prodigious, recite","poor, recite","prodigious, forget","prodigal, recite"],"answer":0,"explanation":"Reciting passages read decades ago shows a prodigious (remarkably great) memory. 'Prodigal' (wasteful) is a look-alike trap.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-106","question":"Fill in the blanks: The villagers, ___ by the floods, were ___ in a relief camp for several weeks.","options":["dispersed, haunted","displayed, housed","displaced, hoarded","displaced, housed"],"answer":3,"explanation":"Floods displace people, who are then housed in relief camps. 'Displayed' and 'hoarded' only resemble the right words.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-107","question":"Fill in the blanks: The treaty was meant to ___ tensions between the two nations, but a border clash soon ___ them.","options":["heighten, reignited","ease, reignited","ease, extinguished","ignore, calmed"],"answer":1,"explanation":"'But' signals the opposite of the treaty's aim: it was meant to ease tensions, but a clash reignited them.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-108","question":"Fill in the blank: The politician's speech was a masterpiece of ___: it said a great deal without committing him to anything.","options":["equivocation","conviction","candour","succinctness"],"answer":0,"explanation":"Equivocation is the use of vague language to avoid committing oneself, as the clause after the colon explains. Candour and conviction are the opposite; succinctness contradicts 'said a great deal'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-109","question":"Fill in the blank: The scheme was ___ in theory but impossible to implement, given the shortage of funds.","options":["sonorous","flawed","sound","unsound"],"answer":2,"explanation":"'But' sets up a contrast: sound (reasonable) in theory, yet impossible in practice. 'Flawed' or 'unsound' would leave no contrast.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-110","question":"Fill in the blank: Instead of admitting his mistake, he tried to ___ the blame on his assistant.","options":["shirk","shift","shrink","shed"],"answer":1,"explanation":"We 'shift the blame on/onto' someone. 'Shirk' means to avoid a duty and does not take 'on his assistant'.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-111","question":"Choose the word that can best replace the phrase 'look into' in the sentence: The committee will look into the complaints before taking a decision.","options":["acknowledge","overlook","despise","investigate"],"answer":3,"explanation":"'Look into' means to investigate or examine. 'Overlook' means to fail to notice or to ignore, almost the opposite.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-112","question":"Fill in the blank: She remained ___ to the danger until it was too late to escape.","options":["obsequious","obvious","oblivious","oblique"],"answer":2,"explanation":"'Oblivious to' means unaware of, which explains why she did not escape in time. The other words only look similar.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-113","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: So each one, acting sensibly for himself, keeps adding cows. Q: Economists call this the tragedy of the commons. R: Imagine a village pasture open to every herder. S: Before long the pasture is stripped bare, and every herder is worse off. T: Each herder gains the full profit from one more cow, while the cost of overgrazing is shared by all.","options":["RTSPQ","RPTSQ","TRPSQ","RTPSQ"],"answer":3,"explanation":"R sets the scene; T explains the incentive; P ('So') draws the individual choice; S shows the collective result; Q names the idea.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-114","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Neither the patients nor the doctors know who is getting what. Q: This 'placebo effect' shows how strongly expectation can shape experience. R: It is also why a new drug must beat the placebo, not merely beat doing nothing. S: In a classic kind of trial, one group of patients receives a new drug and another receives a sugar pill. T: Surprisingly, many in the sugar-pill group also report feeling better.","options":["SPTQR","STPQR","SPQTR","PSTQR"],"answer":0,"explanation":"S describes the trial; P adds the blinding ('who is getting what'); T gives the surprising result; Q names it ('This placebo effect'); R ('also') draws the further consequence.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-115","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Few merchants travelled its whole length; goods passed from hand to hand across many markets. Q: The Silk Road was not a single road at all. R: In that sense, it was as much a highway of ideas as of trade. S: It was a shifting web of caravan routes linking China with the Mediterranean. T: Along with silk and spices, these exchanges carried religions, technologies and even diseases.","options":["QPSTR","QSPTR","SQPTR","QSTPR"],"answer":1,"explanation":"Q opens with the paradox; S explains what it really was; P describes how trade moved; T ('these exchanges') refers back to P; R concludes ('In that sense').","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-116","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Years later, researchers found that the children who waited tended to do better at school. Q: Self-control, it seems, may partly be a luxury of children who can trust that the second sweet will really come. R: Some ate the sweet at once; others found clever ways to distract themselves. S: Recent studies, however, suggest that family background explains much of that link. T: In the famous 'marshmallow test', children were offered one sweet now or two if they waited a few minutes.","options":["RTPSQ","TPRSQ","TRPSQ","TRSPQ"],"answer":2,"explanation":"T introduces the test; R describes the children's behaviour; P gives the later finding; S ('however ... that link') qualifies it; Q draws the conclusion.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-117","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: The Constituent Assembly met for the first time in December 1946. Q: It came into force two months later, on 26 January 1950. R: The Constitution was finally adopted on 26 November 1949. S: That date was chosen because it recalled the Purna Swaraj declaration of 1930. T: Over the next three years it debated every clause of the draft in detail.","options":["PRTQS","PTRQS","PTQRS","TPRQS"],"answer":1,"explanation":"The chronology fixes the order: first meeting (P), three years of debate (T), adoption (R), coming into force (Q), and why that date was chosen (S).","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-118","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Psychologists call this diffusion of responsibility. Q: Studies suggest the opposite: the more people present, the less likely any one of them is to step in. R: The remedy is simple — point to one person and ask them directly to call an ambulance. S: When someone collapses on a crowded street, you might expect help to arrive quickly. T: Each onlooker assumes that someone else has already called for help.","options":["SQTRP","SQPTR","QSTPR","SQTPR"],"answer":3,"explanation":"S states the expectation; Q contradicts it; T explains the onlookers' thinking; P names it ('this'); R offers the remedy that targets one person.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-119","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: The difference lies not in the metal but in the shape. Q: As long as the water it displaces weighs as much as the ship, the ship stays afloat. R: A steel ship weighing thousands of tonnes floats, yet a small steel nail sinks. S: The nail, by contrast, has no hollow space and so displaces too little water to stay up. T: A ship's hull is hollow, so it pushes aside a large volume of water.","options":["RPTQS","RPSTQ","PRTQS","RTPQS"],"answer":0,"explanation":"R poses the puzzle; P points to shape; T explains the hollow hull; Q states the floating condition; S ('by contrast ... no hollow space') must come after the hull is described.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-120","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: A carbon tax raises the price of fuels in proportion to the emissions they cause. Q: Electric cars are becoming cheaper as battery prices fall. R: Firms and households then have a reason to switch to cleaner options. S: The revenue can be returned to citizens so that poorer families are not hurt.","options":["S","R","Q","P"],"answer":2,"explanation":"P, R and S explain how a carbon tax works and how its revenue can be used. Q describes an independent market trend; it is related to clean energy but not to the mechanism of the tax.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-121","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Learning a third language later in life is often said to be easier than learning the second. Q: Children who grow up speaking two languages constantly switch between them. R: Some researchers believe this practice strengthens their ability to control attention. S: Others argue that the evidence for such an advantage is mixed.","options":["R","P","Q","S"],"answer":1,"explanation":"Q, R and S debate whether childhood bilingualism sharpens attention. P shifts to adult learning of a third language, a different question.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-122","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Teenagers' body clocks shift later during puberty. Q: As a result, many cannot fall asleep before eleven at night. R: Adults over sixty-five often wake up earlier than they would like. S: Early school start times therefore leave them chronically short of sleep.","options":["R","S","Q","P"],"answer":0,"explanation":"P, Q and S form a chain about teenagers' sleep and school timings. R is about older adults and breaks the chain, even though it also concerns sleep.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-123","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Corals live in partnership with tiny algae that give them food and colour. Q: When the water becomes too warm, the corals expel the algae. R: Without them, the corals turn white and may starve. S: Some reef fish change sex during their lifetime.","options":["R","P","Q","S"],"answer":3,"explanation":"P, Q and R explain coral bleaching. S is an unrelated fact about reef fish.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-124","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Online reviews strongly influence what people buy. Q: Online shopping grew rapidly during the pandemic lockdowns. R: A product with hundreds of five-star ratings seems a safe choice. S: Yet some sellers pay for fake reviews to boost their ratings.","options":["S","R","Q","P"],"answer":2,"explanation":"P, R and S concern the influence and manipulation of online reviews. Q is about the growth of online shopping in general.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-125","question":"Choose the sentence that best fills the blank in the paragraph: Cities across the world are experimenting with car-free days. On these days, streets fill with cyclists, walkers and children at play. ___ Supporters argue that such glimpses of a quieter city build public support for permanent change.","options":["Many people still need their cars to reach their workplaces on time.","Car sales have risen steadily in most developing countries.","Residents discover how much space and calm cars had been taking.","The bicycle was invented in the nineteenth century."],"answer":2,"explanation":"The next sentence refers to 'such glimpses of a quieter city', so the blank must describe what residents experience on car-free days. The other options break the link.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-126","question":"Choose the sentence that best fills the blank in the paragraph: For decades, economists assumed that people make rational choices. ___ Behavioural economics grew out of the effort to understand these systematic errors.","options":["Yet experiments showed people misjudge risks and follow the crowd predictably.","Rational people, by definition, always try to maximise their income and wealth.","Economics is one of the oldest and most influential of the social sciences.","Many governments employ economists to forecast growth and inflation each year."],"answer":0,"explanation":"The last sentence speaks of 'these systematic errors', so the blank must introduce such errors in contrast to the rationality assumption — hence 'Yet experiments showed ...'. The first trap restates the assumption instead of challenging it.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-127","question":"Choose the set of words that fills the numbered blanks correctly: Scientists are, by temperament, (1) ___: they accept a claim only when the evidence for it is (2) ___. This habit can make them seem cold, but it (3) ___ them from the wishful thinking that misleads so many others.","options":["sceptical, compelling, prevents","credulous, compelling, protects","sceptical, scanty, protects","sceptical, compelling, protects"],"answer":3,"explanation":"Accepting claims only on compelling evidence is scepticism; 'credulous' is the opposite. 'Protects them from' is idiomatic, whereas 'prevents them from' needs a gerund ('from falling into ...').","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-128","question":"Choose the set of words that fills the numbered blanks correctly: The reform was (1) ___ with good intentions but (2) ___ executed. Officials, under pressure to show quick results, (3) ___ the targets rather than the problems the targets were meant to measure.","options":["launched, perfectly, chased","launched, poorly, chased","abandoned, poorly, chased","launched, poorly, ignored"],"answer":1,"explanation":"'But' contrasts good intentions with poor execution; officials under pressure chased the targets themselves instead of the underlying problems. 'Ignored the targets' contradicts 'pressure to show results'.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-129","question":"Choose the set of words that fills the numbered blanks correctly: Unlike his (1) ___ predecessor, who announced every decision with great fanfare, the new director was (2) ___ by nature; he preferred to let results speak and (3) ___ interviews whenever he could.","options":["flamboyant, reticent, sought","reserved, reticent, avoided","flamboyant, garrulous, avoided","flamboyant, reticent, avoided"],"answer":3,"explanation":"A predecessor who loved fanfare was flamboyant; 'Unlike' means the new director was reticent (reserved) and so avoided interviews. 'Reserved' for the predecessor would remove the contrast.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-130","question":"Choose the set of words that fills the numbered blanks correctly: Coastal cities face a (1) ___ threat: as sea levels rise, storms push water further inland, while the land itself is (2) ___ because of the excessive pumping of groundwater. The two effects (3) ___ each other.","options":["twofold, rising, compound","twofold, sinking, compound","single, sinking, compound","twofold, sinking, neutralise"],"answer":1,"explanation":"Two separate dangers are described (a twofold threat); groundwater pumping makes land sink; and the two effects compound (worsen) each other rather than cancel out.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-131","question":"Choose the set of words that fills the numbered blanks correctly: The author's tone throughout is (1) ___; she mocks the pretensions of the rich without ever raising her voice, and her (2) ___ understatements leave the reader (3) ___ long after the book is closed.","options":["wry, clumsy, smiling","solemn, sly, smiling","wry, sly, smiling","wry, sly, weeping"],"answer":2,"explanation":"Quiet mockery is wry; understatement used for humour is sly; and the effect on the reader is amusement (smiling), not grief.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-132","question":"Choose the set of words that fills the numbered blanks correctly: Early-warning systems have (1) ___ cut the death toll from cyclones along India's eastern coast. A storm that might once have killed thousands now (2) ___ only a handful of lives, because people are (3) ___ to shelters days in advance.","options":["dramatically, claims, evacuated","marginally, claims, evacuated","dramatically, spares, evacuated","dramatically, claims, invited"],"answer":0,"explanation":"The fall from thousands to a handful is dramatic; a storm 'claims' lives (it does not 'spare' them, since a handful are still lost); people are evacuated to shelters.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-133","question":"Fill in the blanks: The critics who had ___ the young director's first film were forced to ___ when it won the top prize at the festival.","options":["panned, recant","praised, recant","panned, gloat","ignored, celebrate"],"answer":0,"explanation":"Critics who had panned (harshly criticised) the film would have to recant (take back their opinion) when it won. Those who praised it would have nothing to recant.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-134","question":"Fill in the blanks: His reputation for ___ was such that even his rivals ___ his word without asking for a written contract.","options":["profligacy, trusted","duplicity, accepted","probity, doubted","probity, accepted"],"answer":3,"explanation":"Probity (strict honesty) explains why rivals accepted his word without a contract. Duplicity (deceitfulness) would make them demand one.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-135","question":"Fill in the blanks: The evidence, though ___, was not ___: it pointed strongly towards the accused but did not rule out other explanations.","options":["conclusive, suggestive","suggestive, conclusive","irrelevant, conclusive","suggestive, misleading"],"answer":1,"explanation":"The explanation after the colon shows the evidence was suggestive (pointing strongly) but not conclusive (ruling out alternatives). Reversing the two words reverses the meaning.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-136","question":"Fill in the blanks: What began as a ___ disagreement over parking soon ___ into a feud that divided the whole street.","options":["trivial, subsided","serious, escalated","trivial, escalated","bitter, dwindled"],"answer":2,"explanation":"The contrast between a small beginning and a street-wide feud requires 'trivial' and 'escalated'.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-137","question":"Fill in the blanks: The minister's reply was so ___ that journalists left the press conference no ___ about the government's plans.","options":["detailed, wiser","evasive, wiser","evasive, angrier","candid, clearer"],"answer":1,"explanation":"'None the wiser / no wiser' means knowing no more than before — the result of an evasive reply. A detailed or candid reply would have informed them.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-138","question":"Fill in the blanks: Rather than ___ the problem, the report merely ___ it, describing the symptoms at length but never the causes.","options":["diagnosing, solved","ignoring, documented","diagnosing, documented","documenting, diagnosed"],"answer":2,"explanation":"Describing symptoms without causes is documenting, not diagnosing. Reversing the two verbs contradicts the explanation.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-139","question":"Fill in the blanks: The old law, long ___, was finally ___ by Parliament last year.","options":["obsolete, repealed","relevant, repealed","obsolete, enacted","popular, revived"],"answer":0,"explanation":"An obsolete (outdated) law is naturally repealed (cancelled). A law cannot be 'enacted' after already existing for long.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-140","question":"Fill in the blanks: Her ___ manner put the nervous candidates at ease, and even the most ___ of them began to speak freely.","options":["haughty, confident","brusque, reticent","affable, talkative","affable, reticent"],"answer":3,"explanation":"A friendly (affable) manner puts people at ease; 'even the most reticent' (reserved) beginning to speak shows the effect. 'Even the most talkative' would be no surprise.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-141","question":"Fill in the blank: ___ he had been warned repeatedly, he went ahead with the risky investment.","options":["Inasmuch as","Because","Unless","Even though"],"answer":3,"explanation":"Going ahead despite warnings is a concession, so 'Even though' fits. 'Because' and 'Inasmuch as' would make the warnings the reason for investing, and 'Unless' sets a condition.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-142","question":"Fill in the blank: The new leave rule applies to every employee, ___ rank or length of service.","options":["irrespective of","in view of","on account of","in consideration of"],"answer":0,"explanation":"'Irrespective of' means without regard to. The other phrases mean 'because of', which makes no sense with 'every employee'.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-143","question":"Fill in the blank: The bridge was closed for repairs; ___, traffic had to be diverted through the old town.","options":["nonetheless","accordingly","conversely","otherwise"],"answer":1,"explanation":"The diversion is a consequence of the closure, so 'accordingly' (as a result) fits. 'Nonetheless' signals a contrast.","difficulty":"hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-144","question":"Choose the most logical completion: The experiment was repeated by three independent laboratories, and each obtained the same result; ___","options":["the result was therefore probably a coincidence.","this proved that the original finding was a fraud.","this greatly strengthened confidence in the original finding.","so no further experiments are needed in any field of science."],"answer":2,"explanation":"Independent replication increases confidence in a finding. It cannot prove fraud or suggest coincidence, and the last option overgeneralises.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-145","question":"Choose the most logical and grammatically correct completion: Had the warning been issued an hour earlier, ___","options":["many of the fishermen will certainly return to shore safely.","many of the fishermen return to shore safely.","many of the fishermen could have returned to shore safely.","many of the fishermen had been returning to shore safely."],"answer":2,"explanation":"'Had the warning been issued' is an inverted third conditional (unreal past), so the result clause needs 'could/would have + past participle'.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-146","question":"In which sentence is the word 'discreet' used correctly?","options":["Each discreet step of the process was numbered separately.","The data falls into three discreet categories.","A digital image is made up of discreet dots called pixels.","Please be discreet; nobody else must know about the party."],"answer":3,"explanation":"'Discreet' means careful not to reveal things. The other sentences need 'discrete' (separate, distinct).","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-147","question":"In which sentence is the word 'principal' used correctly?","options":["She is a woman of strong principals.","The principal cause of the delay was the strike.","He refused the bribe on principal.","The principals of physics apply everywhere in the universe."],"answer":1,"explanation":"'Principal' as an adjective means main or chief. The other sentences need 'principle' (a fundamental truth or moral rule).","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-148","question":"Which single word can fill BOTH blanks correctly? (i) Steel is heated and then cooled slowly to ___ it. (ii) He lost his ___ when the meeting dragged on for hours.","options":["temper","harden","mood","anneal"],"answer":0,"explanation":"To temper steel is to treat it with heat; to lose one's temper is to become angry. 'Harden' and 'anneal' fit only (i), and 'lost his mood' is not idiomatic.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-149","question":"Which single word can fill BOTH blanks correctly? (i) The general decided to ___ the fort at dawn. (ii) He suffered a mild heart ___ last winter.","options":["raid","storm","attack","strike"],"answer":2,"explanation":"'Attack the fort' and 'heart attack' both work. 'Storm' and 'raid' fit only (i), and 'heart strike' is not used.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-150","question":"Fill in the blank: The plan, ___ ambitious, is by no means unrealistic.","options":["though","because","unless","so"],"answer":0,"explanation":"'Though ambitious' concedes a point before the contrasting main clause ('by no means unrealistic'). 'Because ambitious' would give a reason, which does not fit.","difficulty":"very-hard","source":"SBI PO · IBPS PO · SSC CGL"},
  {"id":"eng-cloze-rearrangement-151","question":"Fill in the blanks: The committee's findings, ___ they may embarrass a few senior officials, must be published ___ the public is to trust the inquiry at all.","options":["however much, if","so long as, unless","because, lest","whether, so that"],"answer":0,"explanation":"The first blank needs a concession (the findings may embarrass, yet must be published): 'however much'. The second states a condition: 'if the public is to trust'. 'Lest' and 'unless' reverse the logic, and 'whether' needs 'or not'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-152","question":"Fill in the blank: The reviewer conceded the novel's ambition but found its prose so ___ (every sentence weighed down with clauses and qualifications) that the story itself was buried.","options":["terse","limpid","turgid","laconic"],"answer":2,"explanation":"Prose overloaded with clauses is 'turgid' (swollen, pompous). 'Terse' and 'laconic' mean the opposite (very brief), and 'limpid' means clear, which cannot bury a story.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-153","question":"Fill in the blank: The new evidence does not so much ___ the earlier theory as refine it, keeping its core while correcting its dates.","options":["corroborate","overturn","embellish","anticipate"],"answer":1,"explanation":"'Not so much X as refine it, keeping its core' contrasts refinement with destruction, so X is 'overturn'. 'Corroborate' (confirm) does not contrast with keeping the core, which is the trap.","difficulty":"very-hard","source":"CAT · SSC CGL Tier 2"},
  {"id":"eng-cloze-rearrangement-154","question":"Which single word can fill BOTH blanks correctly? (i) The firm must ___ all its debts before the merger is approved. (ii) Factories may not ___ untreated effluent into the river.","options":["settle","release","liquidate","discharge"],"answer":3,"explanation":"'Discharge' means both to pay off a debt and to let out a liquid. 'Settle' and 'liquidate' fit only debts; 'release' fits only effluent.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"eng-cloze-rearrangement-155","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: That figure, however arbitrary, becomes the point from which every later offer is judged. Q: This is why seasoned negotiators try to name a number first, before the other side can set the anchor. R: In a negotiation, the first number spoken aloud has an outsized influence. S: So strong is this pull that even a counter-offer meant to be bold usually lands only a modest step away from that point.","options":["RPQS","RSPQ","RPSQ","PRSQ"],"answer":2,"explanation":"R introduces 'the first number'; P refers to it as 'That figure'; S's 'this pull' and 'that point' continue P; Q's 'This is why' draws the conclusion from the whole effect, so RPSQ.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-156","question":"Fill in the blank: Scarcely had the auditors begun their review ___ the finance director tendered his resignation.","options":["than","when","then","that"],"answer":1,"explanation":"'Scarcely/Hardly ... when' is the correct pair. 'Than' belongs with 'No sooner ... than', the classic trap.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-157","question":"Fill in the blank: The rule exempts small traders, ___ annual turnover falls below the threshold, from filing monthly returns.","options":["whose","whom","who's","which"],"answer":0,"explanation":"The blank shows possession (the traders' turnover), so 'whose'. 'Who's' is 'who is', and 'whom' and 'which' cannot be followed by a noun this way.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-158","question":"Choose the set of words that fills the numbered blanks correctly: Monopolies rarely announce themselves. A platform begins by (1) ___ its users with low prices and generous terms; only when rivals have withered does it begin to (2) ___ the value it has quietly accumulated. By then, switching has become so costly that customers (3) ___ terms they would once have rejected outright.","options":["shunning, squander, protest against","deterring, extract, acquiesce in","courting, extract, acquiesce in","courting, forgo, insist on"],"answer":2,"explanation":"Low prices and generous terms 'court' users; later the platform 'extracts' value; locked-in customers 'acquiesce in' (meekly accept) terms they once would have rejected. 'Deterring' clashes with generous terms and 'forgo' with the predatory turn.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-159","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Coral bleaching happens when stressed corals expel the algae living in their tissues. Q: Since those algae supply most of the coral's food, a bleached reef is starving, not merely pale. R: If water temperatures fall back quickly, the algae can return and the coral may recover. S: Coral reefs attract millions of divers, making them a major source of tourism income. T: Repeated bleaching, however, leaves too little time between events for that recovery.","options":["Q","R","S","T"],"answer":2,"explanation":"P, Q, R and T trace the biology of bleaching and recovery, with T's 'that recovery' picking up R. S shifts to tourism income, which nothing else discusses.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-160","question":"Choose the option that most logically completes the paragraph: Archives are usually imagined as neutral storehouses of the past. Yet every archive is the product of decisions about what to keep, and those decisions were made by people with interests of their own. A colonial land office preserved tax records meticulously but kept no record of the songs sung in the villages it taxed. ___","options":["Songs, after all, are a less reliable source than tax records, since they change with every singer.","Colonial officials were, for the most part, careful administrators who valued accurate accounts.","It follows that oral traditions, not written records, should be the historian's primary source.","The historian must therefore ask not only what such an archive says but why it says it."],"answer":3,"explanation":"The paragraph argues that archives reflect choices about what to keep, so the natural close is that historians must question the selection itself. The first option changes the issue to reliability, and the third overreaches into a rule the paragraph never proposes.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-161","question":"Fill in the blank: The minister's assurance that the scheme would be 'revenue-neutral' proved ___: within a year it had cost the exchequer twice the estimate.","options":["prescient","specious","candid","redundant"],"answer":1,"explanation":"An assurance that sounded plausible but turned out false is 'specious'. 'Prescient' (foresighted) is the opposite, and 'candid' does not fit a claim proved wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · CAT"},
  {"id":"eng-cloze-rearrangement-162","question":"Fill in the blanks: Her objection was not that the policy was ___ but that it was premature: the idea was sound, the timing ___.","options":["impractical, opportune","sound, impeccable","premature, well-chosen","misconceived, ill-judged"],"answer":3,"explanation":"She does not object to the idea ('the idea was sound'), so it was not 'misconceived'; her complaint is the timing, which was 'ill-judged'. The other pairs either repeat 'premature' or praise the timing she is criticising.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-163","question":"The first sentence is given. Arrange P, Q, R and S to complete the paragraph. 1: When a town replaced the traffic signals at a busy junction with a simple roundabout, residents predicted chaos. P: Instead, accidents fell sharply within the first year. Q: The reason, engineers explained, is that a roundabout forces every driver to slow down and look. R: At a signal, by contrast, a driver who sees green often speeds through without checking for others. S: Safety, in other words, can come from uncertainty rather than from clear rules.","options":["PRQS","PQSR","QPRS","PQRS"],"answer":3,"explanation":"'Instead' (P) answers the predicted chaos; Q gives the reason; R's 'by contrast' needs Q's roundabout before it; S ('in other words') sums up. Hence PQRS.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-164","question":"Fill in the blank: Neither the manager nor his assistants ___ aware of the change in policy.","options":["is","has been","was","were"],"answer":3,"explanation":"With 'neither ... nor', the verb agrees with the nearer subject, 'assistants' (plural), so 'were'. 'Was' wrongly agrees with 'the manager'.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-165","question":"Fill in the blank: The company's statement was so ___ (it neither confirmed nor denied the specific allegations) that analysts read it as a tacit admission.","options":["emphatic","categorical","equivocal","forthright"],"answer":2,"explanation":"A statement that neither confirms nor denies is 'equivocal'. 'Emphatic', 'categorical' and 'forthright' all describe clear, direct statements, the opposite.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-166","question":"Fill in the blank: Had the dam's engineers heeded the geologists' warnings, the displaced villagers ___ in relief camps even now.","options":["would not have lived","would not be living","will not be living","had not been living"],"answer":1,"explanation":"This is a mixed conditional: a past condition ('Had ... heeded') with a present result ('even now'), so 'would not be living'. 'Would not have lived' puts the result in the past and clashes with 'even now'.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-167","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: The answer, it turns out, lies less in the ink than in the paper. Q: Why do some medieval manuscripts survive in near-perfect condition while printed books from the nineteenth century crumble at a touch? R: Medieval scribes wrote on parchment made from animal skin, which is remarkably stable. S: The cheap paper of the nineteenth century, by contrast, was made from wood pulp laced with acids that slowly ate it from within.","options":["QRSP","PQRS","QPRS","QPSR"],"answer":2,"explanation":"The question (Q) must come before 'The answer' (P); P points to the material, R explains parchment, and S's 'by contrast' must follow R. So QPRS.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-168","question":"Fill in the blank: The scientist's tone in the interview was ___; she defended her data vigorously but conceded, with evident discomfort, that one of her central assumptions had never been tested.","options":["defensive yet candid","smug and evasive","detached and clinical","apologetic and contrite"],"answer":0,"explanation":"Vigorous defence shows defensiveness, and the uncomfortable admission shows candour. She did not evade (she conceded), was not detached (evident discomfort) and was not contrite (she defended her data).","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-169","question":"Fill in the blanks: The new law is ___ in its aims but ___ in its drafting, leaving courts to guess at what Parliament meant.","options":["ambitious, precise","laudable, slipshod","modest, meticulous","obscure, careless"],"answer":1,"explanation":"'But' needs a positive-negative contrast, and courts guessing at the meaning shows careless drafting: 'laudable, slipshod'. 'Obscure, careless' are both negative, so 'but' makes no sense.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-170","question":"Choose the grammatically correct completion: Only after the auditors had traced every single transfer ___","options":["the board realised how deep the fraud ran.","did the board realised how deep the fraud ran.","had the board realise how deep the fraud ran.","did the board realise how deep the fraud ran."],"answer":3,"explanation":"A sentence opening with 'Only after ...' takes inversion with an auxiliary plus the base verb: 'did the board realise'. 'Did ... realised' doubles the past tense, and the plain order skips the inversion.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-171","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: In one trial, patients with chronic back pain were handed pills and told plainly that they contained no medicine. Q: Placebos have long been thought to work only through deception. R: Many of them nonetheless reported less pain than a group given no pills at all. S: If the ritual of treatment, rather than belief in a drug, does part of the healing, doctors may have more tools than they realise. T: Recent research has begun to unsettle that assumption.","options":["QPRTS","QTPRS","TQPRS","QTPSR"],"answer":1,"explanation":"Q states the belief; T's 'that assumption' refers to it; P gives the trial; R's 'them' and 'nonetheless' follow P; S draws the implication. Hence QTPRS.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-172","question":"Fill in the blank: The two firms' accounts of the meeting were so ___ that the arbitrator concluded at least one of them must be lying.","options":["corroborative","complementary","irreconcilable","indistinguishable"],"answer":2,"explanation":"If one party must be lying, the accounts contradict each other: 'irreconcilable'. 'Complementary' means fitting together, a common confusion with 'contradictory', and 'indistinguishable' or 'corroborative' accounts would agree.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-173","question":"Choose the set of words that fills the numbered blanks correctly: Austerity during a slump is (1) ___ by an old intuition: a household in debt tightens its belt, so why not a government? The analogy is (2) ___. When households and the government all cut spending at once, one person's saving becomes another's lost income, and the debt the cuts were meant to reduce may (3) ___ as a share of a shrinking economy.","options":["underpinned, misleading, rise","undermined, apt, fall","underpinned, apt, rise","underpinned, misleading, vanish"],"answer":0,"explanation":"The intuition supports ('underpins') austerity; the rest of the passage attacks the analogy, so it is 'misleading'; and debt measured against a shrinking economy can 'rise'. 'Apt' contradicts the argument, and 'vanish' overstates it.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-174","question":"Fill in the blank: The witness's account does not square ___ the timeline established by the phone records.","options":["with","to","against","by"],"answer":0,"explanation":"The idiom is 'square with', meaning to agree or be consistent with. 'Square to' or 'square against' are not used in this sense.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-175","question":"Fill in the blank: After five years of losses, the board finally decided to ___ and sell the loss-making unit, accepting the painful write-down.","options":["bite the bullet","beat about the bush","burn the midnight oil","let sleeping dogs lie"],"answer":0,"explanation":"'Bite the bullet' means to face a painful but necessary decision, which fits accepting a write-down. 'Let sleeping dogs lie' would mean avoiding the issue, the opposite.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-176","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Within months, waiting times on paper had fallen dramatically. Q: A health ministry once decided to fine hospitals whose emergency patients waited more than four hours to be seen. R: Patients were being kept in ambulances outside the doors, where, officially, their wait had not yet begun. S: Inspectors who visited, however, soon discovered how the improvement had been achieved. T: The lesson is an old one: a measure, once it becomes a target, tends to report what managers want rather than what is true.","options":["QPRST","QPSRT","QSPRT","TQPSR"],"answer":1,"explanation":"Q sets up the fine, P gives the result, S's 'however ... how' leads into the trick revealed in R, and T's 'The lesson' needs the whole story before it. Opening with T fails because 'The lesson' has nothing to refer to.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-177","question":"Fill in the blanks: The drought will ___ the price of pulses, and the higher prices will in turn ___ the poorest families most.","options":["affect, effect","effect, affect","affect, affect","effect, effect"],"answer":2,"explanation":"Both blanks need the verb meaning 'to influence': 'affect'. 'Effect' as a verb means 'to bring about' (effect a change), so 'effect the price' would wrongly mean creating the price.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-178","question":"Where does the following sentence best fit in the paragraph? 'Yet this very abundance is what makes them fragile.' (A) Monocultures of a single high-yielding variety now cover vast areas of farmland. (B) They feed millions and keep food prices low. (C) A disease that can attack one plant can attack them all, because every plant shares the same genes. (D) The Irish potato famine of the 1840s showed how quickly such a failure can spread.","options":["After sentence (A)","After sentence (B)","After sentence (C)","After sentence (D)"],"answer":1,"explanation":"'This very abundance' must follow the sentence about feeding millions and keeping prices low (B), and 'fragile' sets up the disease risk in (C). After (A), the praise in (B) would awkwardly follow the warning.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-179","question":"Fill in the blank: The surprise testimony threw the defence's entire case ___ disarray.","options":["into","in","at","under"],"answer":0,"explanation":"The idiom is 'throw into disarray' (movement into a state). 'In disarray' describes the state itself (the case was in disarray) but does not follow 'threw'.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-180","question":"Choose the set of words that fills the numbered blanks correctly: Early critics of photography feared that it would (1) ___ painting: why labour over a portrait when a machine could record a face in minutes? What happened instead was more (2) ___. Freed from the duty of recording likeness, painters began to explore what a camera could not capture: light, mood, the (3) ___ of perception itself.","options":["supplement, predictable, objectivity","supplant, predictable, subjectivity","supplant, interesting, subjectivity","emulate, interesting, permanence"],"answer":2,"explanation":"The fear was that photography would 'supplant' (replace) painting; 'What happened instead' signals a more 'interesting' outcome; and what a camera cannot capture is the 'subjectivity' of perception. 'Predictable' clashes with 'instead'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-181","question":"Fill in the blank: The candidate's answers were ___ rather than evasive: brief, but each one addressed the question directly.","options":["verbose","oblique","rambling","laconic"],"answer":3,"explanation":"Brief but direct answers are 'laconic'. 'Oblique' means indirect, which is exactly what 'rather than evasive' rules out; 'verbose' and 'rambling' contradict 'brief'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-182","question":"Fill in the blank: Each of the proposals submitted by the consultants ___ been rejected by the board.","options":["have","has","were","are"],"answer":1,"explanation":"The subject is 'Each', which is singular, so 'has'. The plural 'proposals' and 'consultants' are inside prepositional phrases and do not control the verb.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-183","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Himalayan glaciers are often called the water towers of Asia. Q: In the dry months they release meltwater that keeps rivers flowing before the monsoon arrives. R: As they shrink, that flow at first rises, giving a false sense of plenty. S: Once a glacier has lost enough ice, its meltwater begins to decline, often permanently. T: Glaciers also carve the U-shaped valleys that make mountain landscapes so distinctive.","options":["Q","R","S","T"],"answer":3,"explanation":"P, Q, R and S follow one thread: glaciers as a water supply and what their shrinking does to river flow. T is about glaciers too, but about landforms, which is the trap.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-184","question":"Fill in the blank: The court held that the confession, though ___, was inadmissible, because it had been obtained without the accused being told of his right to remain silent.","options":["voluntary","coerced","fabricated","retracted"],"answer":0,"explanation":"'Though' needs a contrast with 'inadmissible': even a 'voluntary' confession was thrown out on procedural grounds. A coerced, fabricated or retracted confession would be a reason for exclusion, not a contrast.","difficulty":"very-hard","source":"CAT · SSC CGL Tier 2"},
  {"id":"eng-cloze-rearrangement-185","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: For most of history, a city's size was limited by how far its food could travel before it spoiled. P: Grain could be moved, but slowly and at great cost over land. Q: Fresh milk, meat and vegetables had to come from farms within a day's cart ride. R: Refrigerated rail cars and, later, ships changed that arithmetic within a single generation. S: Rivers and coasts helped, which is why so many great cities grew beside water. 6: Today the food on a city dweller's plate may have crossed several oceans.","options":["PSQR","QPRS","QSPR","QPSR"],"answer":3,"explanation":"Q gives the perishable foods; P's 'Grain could be moved, but ... over land' contrasts with them; S explains how water transport helped that movement; R's 'changed that arithmetic' sums up the old limits and leads into 6.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-186","question":"Choose the option that most logically completes the paragraph: Crime statistics can rise for two quite different reasons: because more crimes are committed, or because more of them are reported. When a police station staffed entirely by women opened in one district, recorded cases of domestic violence there nearly doubled. ___","options":["This proves that the district became far more violent after the station opened.","Clearly, women officers are less effective at preventing crime than men.","Women had likely grown more willing to report abuse, not suffered more of it.","It is therefore impossible to draw any conclusion from crime statistics."],"answer":2,"explanation":"The first sentence sets up 'more reported' as an alternative explanation, and a women-run station plausibly encourages reporting. 'Proves' and 'impossible' are extreme, and the second option ignores the reporting explanation the paragraph sets up.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-187","question":"Fill in the blank: The professor, along with her two research students, ___ invited to present the findings in Geneva.","options":["have been","were","has been","are"],"answer":2,"explanation":"'Along with', like 'as well as', does not make the subject plural. The subject is 'The professor', so 'has been'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-188","question":"Fill in the blank: The phrase 'begging the question' is widely used to mean 'raising the question', but in logic it names a ___: an argument that assumes the very conclusion it sets out to prove.","options":["paradox","fallacy","tautology","hypothesis"],"answer":1,"explanation":"Circular argument is a flaw in reasoning, a 'fallacy'. A tautology is a statement true by its form, not a defective argument, and a paradox is a seeming contradiction.","difficulty":"very-hard","source":"CAT · SSC CGL Tier 2"},
  {"id":"eng-cloze-rearrangement-189","question":"Fill in the blanks: The drug's benefits were ___ (barely distinguishable from those of a placebo), while its side effects were anything but ___.","options":["substantial, serious","marginal, severe","negligible, significant","marginal, trivial"],"answer":3,"explanation":"Benefits close to a placebo's are 'marginal'; 'while' signals contrast, so the side effects were serious, i.e. 'anything but trivial'. 'Anything but severe' would make them mild, which destroys the contrast.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-190","question":"Fill in the blank: I would rather you ___ the matter to the police yourself tomorrow.","options":["report","reported","had reported","will report"],"answer":1,"explanation":"'Would rather' + a different subject takes the past tense for a present or future wish: 'I would rather you reported'. 'Had reported' is for regret about the past and clashes with 'tomorrow'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-191","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: By the late twentieth century, the change was so complete that a researcher publishing only in her own language risked being ignored altogether. Q: In the nineteenth century, a serious chemist was expected to read German, and a mathematician French. R: This brought undeniable convenience, since a single language let results travel instantly. S: Over the following decades, English steadily displaced both as the common tongue of science. T: It also carried a cost: ideas first framed in other languages now reach the world only if someone translates them.","options":["QSPRT","QSRTP","SQPRT","QPSRT"],"answer":0,"explanation":"Q sets the old situation; S's 'both' refers to German and French; P's 'the change' is S's displacement; R and T then weigh its convenience and its cost ('also'). S cannot open the paragraph because 'both' would have no referent.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-192","question":"In the sentence below, which word is used INCORRECTLY? The council's decision to privatise the water supply was contentious; critics argued that it would exasperate inequality, while supporters claimed it would curb waste.","options":["privatise","contentious","exasperate","curb"],"answer":2,"explanation":"'Exasperate' means to irritate a person; the word needed is 'exacerbate' (to make a problem worse). The other words fit their contexts.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-193","question":"Fill in the blank: The forecast proved ___ only in hindsight; at the time, its warnings were dismissed as alarmist.","options":["prophetic","erroneous","premature","hysterical"],"answer":0,"explanation":"A forecast that turns out right after being dismissed was 'prophetic'. 'Hysterical' is what critics called it at the time, not what it proved to be, and 'erroneous' reverses the meaning.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-194","question":"Choose the set of words that fills the numbered blanks correctly: A good editor is (1) ___ rather than intrusive. She does not impose her own voice on a manuscript but helps the writer sound (2) ___ like himself, cutting what is (3) ___ so that what matters can be heard.","options":["domineering, less, essential","self-effacing, more, extraneous","self-effacing, less, extraneous","self-effacing, more, indispensable"],"answer":1,"explanation":"'Rather than intrusive' calls for 'self-effacing'; she helps the writer sound 'more' like himself; and she cuts what is 'extraneous' (irrelevant), not what is indispensable.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-195","question":"Fill in the blank: The new procurement policy is ___ to the interests of small farmers, who will lose the guaranteed prices they have relied on for years.","options":["amenable","conducive","germane","inimical"],"answer":3,"explanation":"A policy that takes away farmers' guaranteed prices is harmful to them: 'inimical'. 'Conducive to' means favourable, and 'germane' only means relevant.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-196","question":"Choose the grammatically correct and logical completion: The more a city spends on widening its roads, ___","options":["the less it attracts traffic often.","more traffic it often ends up attracting.","the more traffic it often ends up attracting.","the more it often ends up to attract traffic."],"answer":2,"explanation":"The comparative structure 'The more ..., the more ...' needs 'the' in both halves, and 'end up' takes a gerund ('attracting'). Wider roads tend to draw more traffic, so 'the less' gets the logic wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-197","question":"Fill in the blank: Many a student ___ failed to notice the trick in the question.","options":["has","have","were","are"],"answer":0,"explanation":"'Many a' + singular noun takes a singular verb, so 'has'. It feels plural in meaning, which is the trap.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-198","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: It was the first time the village had elected a woman as its head. Q: Within a year, she had persuaded the council to spend its funds on a water pipeline rather than a new community hall. R: The women who had walked two kilometres for water every morning noticed the difference first. S: Her opponents, who had held the post for twenty years, mocked her for having no experience of public life.","options":["PQSR","SPQR","PSQR","PQRS"],"answer":2,"explanation":"P introduces 'a woman', the antecedent of 'Her' in S; S's mockery belongs to the start of her term, before 'Within a year' (Q); R gives the result of the pipeline. Hence PSQR.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-199","question":"Which single word can fill BOTH blanks correctly? (i) Doctors managed to ___ the spread of the infection within a week. (ii) The police needed a warrant to ___ the minister on charges of fraud.","options":["detain","arrest","check","halt"],"answer":1,"explanation":"'Arrest' means both to stop a process and to take someone into custody. 'Check' and 'halt' fit only (i), and 'detain' fits only (ii).","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"eng-cloze-rearrangement-200","question":"Fill in the blank: After two days of talks, the negotiators finally hammered ___ a compromise in the early hours of the morning.","options":["in","off","up","out"],"answer":3,"explanation":"'Hammer out' means to reach an agreement after long discussion. 'Hammer in' means to drive something in or insist on it repeatedly.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-201","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Paradoxically, the more people who witness an emergency, the less likely any one of them is to help. Q: Each assumes that someone else has already called for help, or is better placed to do so. R: One might expect a person collapsing on a crowded street to receive help sooner than one collapsing on an empty road. S: In short, responsibility spread across many shoulders ends up resting on none. T: This is why first-aid trainers teach people to single out one bystander and give that person a specific task, restoring the responsibility the crowd had dissolved.","options":["RPQST","RPQTS","PRQST","RQPST"],"answer":0,"explanation":"R states the natural expectation, P overturns it ('Paradoxically'), Q gives the reason, S sums it up ('In short'), and T's 'the responsibility the crowd had dissolved' needs S's idea before it. Hence RPQST.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-202","question":"Fill in the blank: The auditor's report was ___ in its criticism: it named the officials responsible and listed every irregular payment.","options":["perfunctory","unsparing","oblique","muted"],"answer":1,"explanation":"Naming officials and listing every payment is criticism that holds nothing back: 'unsparing'. 'Perfunctory' (done for form's sake), 'oblique' (indirect) and 'muted' all suggest the opposite.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-203","question":"Choose the set of words that fills the numbered blanks correctly: Translation is often (1) ___ as a mechanical task, a matter of swapping one word for another. Anyone who has tried to translate a joke knows better. Humour depends on (2) ___ that one language possesses and another lacks, so the translator must often (3) ___ the original altogether and invent a new joke that does the same work.","options":["dismissed, ambiguities, abandon","celebrated, ambiguities, preserve","dismissed, certainties, abandon","dismissed, ambiguities, transcribe"],"answer":0,"explanation":"'Knows better' shows the mechanical view is being 'dismissed' as wrong; jokes rest on double meanings ('ambiguities'); and inventing a new joke means the translator must 'abandon' the original. 'Preserve' and 'transcribe' contradict 'invent a new joke'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-204","question":"Fill in the blank: ___ the risks involved, the expedition's sponsors insisted on full insurance cover for every member.","options":["Given","Despite","Notwithstanding","Regardless"],"answer":0,"explanation":"The insurance demand follows because of the risks, so the connector must show cause: 'Given'. 'Despite' and 'Notwithstanding' signal contrast, and 'Regardless' would need 'of'.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-205","question":"Fill in the blank: She has been working at the institute ___ the past eleven years.","options":["since","for","from","by"],"answer":1,"explanation":"A period of time ('the past eleven years') takes 'for'; 'since' needs a point in time (since 2015). 'From' would need 'to' or 'till'.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-206","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: The printing press made books cheaper, but it also made errors permanent. Q: A scribe's slip spoiled a single copy; a typesetter's slip was reproduced a thousand times. R: Early printers therefore hired correctors whose only job was to read proofs before a print run. S: Some printed Bibles became notorious for misprints that changed the meaning of entire verses. T: Handwritten manuscripts were often decorated with gold leaf and elaborate illustrations.","options":["Q","R","S","T"],"answer":3,"explanation":"P, Q, R and S all develop the theme of printed errors and how they spread. T, about decoration in manuscripts, mentions the same period but not the theme.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-207","question":"Fill in the blank: He spoke with such ___ about a subject he had clearly never studied that the experts in the audience exchanged amused glances.","options":["diffidence","hesitancy","assurance","reticence"],"answer":2,"explanation":"The irony lies in a confident manner without real knowledge, so 'assurance'. 'Diffidence', 'hesitancy' and 'reticence' all mean shyness or holding back, which would not amuse experts.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-208","question":"Choose the option that most logically completes the paragraph: For decades, dieters were told that a calorie is a calorie, whatever its source. In a narrow sense this is true: burnt in a laboratory, a gram of sugar and a gram of protein release fixed amounts of energy. But the body is not a laboratory furnace. ___","options":["Sugar, therefore, must contain more calories per gram than protein ever does.","Digesting protein, say, burns more energy than digesting sugar, and foods differ in satiety.","Laboratory measurements of food energy are, for this reason, completely unreliable and misleading.","Dieters should therefore stop counting calories and eat whatever they like."],"answer":1,"explanation":"'The body is not a laboratory furnace' needs an example of the body treating equal calories differently, which the protein-digestion point gives. The paragraph has just said lab measurements are true 'in a narrow sense', so calling them unreliable contradicts it.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-209","question":"Fill in the blanks: Critics called the merger a ___ of two weak firms, arguing that combining their debts would ___ rather than cure their problems.","options":["marriage of convenience, compound","match made in heaven, compound","marriage of convenience, alleviate","hostile takeover, resolve"],"answer":0,"explanation":"Critics would call it a 'marriage of convenience' (a union for expediency), and 'rather than cure' needs an opposite: 'compound' (worsen). 'Alleviate' and 'resolve' are close to 'cure' and break the contrast.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-210","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: The first maps of the city's metro network were drawn to scale, with every curve of track shown faithfully. P: Passengers found them confusing, since stations in the centre were crammed together while those in the suburbs sprawled across the page. Q: A draughtsman then proposed a radical alternative: straight lines, fixed angles and equal spacing between stations, whatever the real distances. R: Officials doubted that travellers would accept a map that was, strictly speaking, wrong. S: Yet the public adopted it almost at once, for a rider underground cares about sequence and connections, not distance. 6: Nearly every metro map in the world now follows the same principle.","options":["QPRS","PRQS","PQRS","PQSR"],"answer":2,"explanation":"P states the problem with the scale maps; Q's 'then' offers the alternative; R records the officials' doubt; S's 'Yet' answers that doubt and leads into 6. Hence PQRS.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-211","question":"Fill in the blank: The evidence against him was ___: no single fact settled the matter, but taken together they left little room for doubt.","options":["conclusive","flimsy","direct","cumulative"],"answer":3,"explanation":"Evidence that persuades only when the pieces are added together is 'cumulative'. 'Flimsy' contradicts 'little room for doubt', and 'conclusive' and 'direct' contradict 'no single fact settled the matter'.","difficulty":"very-hard","source":"CAT · SSC CGL Tier 2"},
  {"id":"eng-cloze-rearrangement-212","question":"Fill in the blank: The court ruled that the clause was void because it was ___ to public policy.","options":["contrary","opposite","adverse","averse"],"answer":0,"explanation":"The fixed legal phrase is 'contrary to public policy'. 'Averse to' describes a person's dislike, and 'adverse' means harmful, which does not make a clause void.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-213","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: The money already spent cannot be recovered whichever way the decision goes. Q: A government that has poured years and crores into an unfinished project often argues that abandoning it now would waste everything spent so far. R: The only sensible question, then, is whether the benefits still to come will justify the costs still to be paid. S: The argument sounds prudent, but it confuses the past with the future. T: Economists call this error the sunk-cost fallacy, and it keeps many doomed projects alive for decades.","options":["QPSRT","QSRPT","SQPRT","QSPRT"],"answer":3,"explanation":"Q states the argument; S ('The argument') judges it; P explains why the past spending is irrelevant; R's 'then' draws the conclusion from P; T names the error. Hence QSPRT.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-214","question":"Fill in the blank: The suspect could not ___ for his whereabouts on the night of the robbery.","options":["explain","answer","account","justify"],"answer":2,"explanation":"'Account for' means to give a satisfactory record or explanation of something. 'Explain' and 'justify' do not take 'for', and 'answer for' means to take responsibility or be punished.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-215","question":"Which single word can fill BOTH blanks correctly? (i) The novel's ___ is so intricate that many readers lose track of who betrayed whom. (ii) Every hour the navigator had to ___ the ship's position on the chart.","options":["scheme","design","plot","trace"],"answer":2,"explanation":"'Plot' is both the storyline of a novel and the act of marking a position on a chart. 'Trace' fits only (ii), and 'scheme' and 'design' do not fit the navigator's task.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"eng-cloze-rearrangement-216","question":"Fill in the blanks: Paradoxically, the very ___ of antibiotics has hastened their ___: every unnecessary prescription gives resistant bacteria another chance to multiply.","options":["success, obsolescence","scarcity, obsolescence","success, proliferation","failure, decline"],"answer":0,"explanation":"The paradox is that success led to overuse, which breeds resistance and makes the drugs useless: 'success, obsolescence'. 'Success, proliferation' has no paradox, and 'scarcity' could not explain overprescription.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-217","question":"Fill in the blank: The two clauses of the agreement are mutually ___; honouring one makes it impossible to honour the other.","options":["inclusive","exclusive","dependent","compatible"],"answer":1,"explanation":"Two things that cannot both happen are 'mutually exclusive'. 'Compatible' and 'inclusive' say the opposite, and 'dependent' would mean each needs the other.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-218","question":"Where does the following sentence best fit in the paragraph? 'The trouble is that such a promise is only as good as the bank's ability to keep it.' (A) A bank takes in deposits that customers can withdraw at any time, and lends them out for years. (B) This works because, on any given day, only a few depositors want their money back. (C) Each depositor is, in effect, promised that her money is available on demand. (D) If enough of them doubt this at once, the doubt becomes self-fulfilling, and the bank fails.","options":["After sentence (A)","After sentence (B)","After sentence (C)","After sentence (D)"],"answer":2,"explanation":"'Such a promise' must follow the sentence that states the promise (C), and the sentence then leads naturally into (D)'s doubt and collapse.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-219","question":"Fill in the blank: Though he professed to be ___ about the outcome of the election, he refreshed the results page every few minutes.","options":["apprehensive","indifferent","ecstatic","informed"],"answer":1,"explanation":"'Though' sets his claimed attitude against his restless behaviour, so he claimed to be 'indifferent'. 'Apprehensive' would match his behaviour and leave no contrast.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-220","question":"Choose the set of words that fills the numbered blanks correctly: Folk remedies are not (1) ___ worthless; aspirin's ancestor was a willow-bark tea. But for every remedy that survived testing, many more were found to be (2) ___ at best and harmful at worst. Tradition can (3) ___ a hypothesis worth testing; it cannot substitute for the test.","options":["necessarily, inert, prove","necessarily, inert, suggest","entirely, beneficial, prove","always, effective, suggest"],"answer":1,"explanation":"'Not necessarily worthless' fits the aspirin example; 'at best ... harmful at worst' needs a mild negative, 'inert' (having no effect); and tradition can only 'suggest' a hypothesis, since it 'cannot substitute for the test'. 'Prove' contradicts that last clause.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-221","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Instead, they found that the plants grown with music did no better than those grown in silence. Q: A group of students set out to test the popular claim that plants grow faster when music is played to them. R: They grew two batches of seedlings under identical light, soil and water, playing music to only one. S: Their conclusion was that the claim, however charming, had no support in their data.","options":["QRPS","QPRS","RQPS","QRSP"],"answer":0,"explanation":"Q sets up the claim, R describes the method, P's 'Instead' reports the result against expectation, and S concludes. 'They' in R needs Q before it, so R cannot open.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-222","question":"Fill in the blank: The committee's recommendations were ___ rather than binding, so the ministry was free to ignore them, and did.","options":["mandatory","statutory","peremptory","advisory"],"answer":3,"explanation":"Recommendations the ministry may ignore are 'advisory'. 'Mandatory', 'statutory' and 'peremptory' all suggest force or obligation, the opposite of 'rather than binding'.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-223","question":"Fill in the blank: The revised rules will come ___ force on the first of next month.","options":["in","to","under","into"],"answer":3,"explanation":"The fixed phrase is 'come into force' (begin to apply). 'In force' describes rules already operating (the rules are in force), not the start.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-224","question":"Fill in the blanks: To call the reform a ___ would be unfair; it has achieved a few modest gains. To call it a success, however, would be ___.","options":["fiasco, generous","triumph, generous","fiasco, accurate","failure, harsh"],"answer":0,"explanation":"Modest gains make 'fiasco' unfair, yet calling the reform a success would overpraise it: 'generous'. 'Accurate' contradicts 'however', and 'harsh' makes no sense for praise.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-225","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: Bats find their way in the dark by emitting high-pitched calls and listening for the echoes. Q: From the delay and pitch of each echo, a bat can judge the distance and movement of an insect. R: Some moths have evolved ears tuned to these calls and dive to the ground when they hear one. S: Others produce clicks of their own that seem to jam the bat's sonar. T: Bats are the only mammals capable of true powered flight.","options":["Q","R","S","T"],"answer":3,"explanation":"The paragraph is about bat echolocation and how moths counter it; R and S shift to moths but stay on that theme. T is a true fact about bats but has nothing to do with sonar.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-226","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: The discovery of oil can, surprisingly, leave a country poorer. Q: As oil exports soar, foreign money floods in and pushes up the value of the local currency. R: A dearer currency makes the country's other exports, from textiles to farm goods, harder to sell abroad. S: When the oil runs out or its price collapses, the country finds that the industries it once had are gone. T: Factories close, and workers drift into the oil sector or the government payroll it funds.","options":["PQRST","QRPTS","PQRTS","PRQTS"],"answer":2,"explanation":"P states the paradox; Q and R give the currency mechanism; T describes the decline that follows; S delivers the final blow once oil fails. Putting T after S repeats what S has already said ('industries ... are gone').","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-227","question":"Fill in the blank: The spokesperson's ___ reply ('We do not comment on speculation') told reporters nothing they did not already know.","options":["perfunctory","effusive","revealing","impassioned"],"answer":0,"explanation":"A stock phrase given out of routine is 'perfunctory'. 'Revealing' contradicts 'told reporters nothing', and 'effusive' and 'impassioned' do not fit a curt formula.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-228","question":"Choose the set of words that fills the numbered blanks correctly: Memory is less a recording than a (1) ___. Each time we recall an event, we rebuild it from fragments, and in the rebuilding we may (2) ___ details we have since learnt or imagined. This is why a witness can be both entirely (3) ___ and entirely wrong.","options":["reconstruction, discard, mistaken","replica, incorporate, sincere","reconstruction, incorporate, deceitful","reconstruction, incorporate, sincere"],"answer":3,"explanation":"'Rebuild it from fragments' means memory is a 'reconstruction'; later details get 'incorporated'; so a witness can be 'sincere' yet wrong. 'Deceitful and wrong' loses the paradox that 'both ... and' sets up.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-229","question":"Fill in the blank: The bill was passed ___ the strong objections of the opposition.","options":["despite","despite of","in spite","inspite of"],"answer":0,"explanation":"'Despite' takes no 'of', while 'in spite' must be followed by 'of' and written as two words. 'Despite of' and 'inspite of' are common errors.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-230","question":"Choose the option that most logically completes the paragraph: Economists distinguish between risk, where the odds of each outcome are known, and uncertainty, where they are not. A gambler at a roulette wheel faces risk; a firm launching a product unlike anything on the market faces uncertainty. ___","options":["The gambler, therefore, is more likely than the firm to make money.","So the firm cannot just calculate its way to a decision, as the gambler can.","Roulette, after all, becomes a game of pure skill once all the odds are known.","Firms should therefore avoid launching new products altogether."],"answer":1,"explanation":"The distinction is about whether odds are known, so the natural consequence is that the firm cannot compute an expected outcome and must use judgement. The other options draw conclusions about profit, skill or avoidance that the distinction does not support.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-231","question":"Fill in the blank: By the time the ambulance arrived, the injured man ___ consciousness.","options":["has lost","lost","had lost","was losing"],"answer":2,"explanation":"An action completed before another past event ('By the time ... arrived') takes the past perfect: 'had lost'. 'Has lost' is present perfect and cannot pair with a past time clause.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-232","question":"Which single word can fill BOTH blanks correctly? (i) The Supreme Court agreed to ___ the execution pending a review of the case. (ii) You are welcome to ___ for dinner if the rain does not stop.","options":["defer","suspend","remain","stay"],"answer":3,"explanation":"'Stay' means both to suspend a legal order (stay an execution) and to remain somewhere. 'Defer' and 'suspend' fit only (i), and 'remain' fits only (ii).","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"eng-cloze-rearrangement-233","question":"Sentences 1 and 6 are given. Arrange P, Q, R and S between them. 1: In the eighteenth century, sailors on long voyages died of scurvy in such numbers that it was accepted as a cost of going to sea. P: A naval surgeon divided a group of sick sailors into pairs and gave each pair a different remedy. Q: Those who received oranges and lemons recovered within days, while the others barely improved. R: Yet, astonishingly, it took the navy decades more to make citrus juice a standard ration. S: His was one of the first controlled trials in the history of medicine. 6: Knowledge, it seems, is not the same as action.","options":["PQSR","PQRS","PSQR","QPSR"],"answer":0,"explanation":"P describes the experiment, Q its result, S ('His') judges its importance, and R's 'Yet ... decades more' sets up 6's point about knowledge and action. Putting S last would separate 'His' from the surgeon and break the link between R and 6.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-234","question":"Fill in the blank: The new chief executive's first act was to ___ the bloated middle management, cutting three layers of supervisors.","options":["bolster","augment","insulate","prune"],"answer":3,"explanation":"Cutting layers of supervisors is to 'prune' (cut back). 'Bolster' and 'augment' mean to strengthen or increase, the opposite, and 'insulate' means to protect.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-235","question":"Fill in the blanks: The historian's account is ___ without being ___: it admires its subject's achievements but does not look away from his cruelties.","options":["sympathetic, hagiographic","hostile, condemnatory","sympathetic, balanced","dispassionate, partisan"],"answer":0,"explanation":"Admiring the achievements is 'sympathetic'; refusing to hide the cruelties means it is not 'hagiographic' (uncritically worshipful). 'Sympathetic without being balanced' contradicts the second half of the sentence.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-236","question":"Fill in the blank: It is no use ___ over the results now; the examination is over.","options":["to worry","worrying","worry","worried"],"answer":1,"explanation":"The fixed pattern 'It is no use' is followed by a gerund: 'It is no use worrying'. The infinitive 'to worry' is the usual trap.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-237","question":"In the following set, one sentence does not belong to the paragraph formed by the others. Identify it. P: A city's trees do far more than decorate its streets. Q: Their shade can lower the surface temperature of a pavement by many degrees on a summer afternoon. R: Their roots hold soil in place and help rainwater soak into the ground instead of overwhelming the drains. S: Planting a sapling is easy; keeping it alive through its first few dry summers is far harder. T: Studies have even linked leafy streets to lower stress among residents.","options":["Q","R","S","T"],"answer":2,"explanation":"P announces the theme (what trees do for a city) and Q, R and T each list a benefit. S is about trees but discusses the difficulty of growing them, not their benefits.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-238","question":"Choose the option that most logically completes the paragraph: Most people assume that a lie detector detects lies. It does not. It measures pulse, breathing and sweating, which rise with anxiety. ___","options":["It is therefore the most reliable way of identifying liars.","Anxiety, after all, is always and everywhere a sure sign of guilt.","Pulse and breathing are, for this reason, impossible to measure accurately.","So an honest but nervous suspect may fail, while a calm liar may pass."],"answer":3,"explanation":"If the machine measures anxiety rather than lying, it will misjudge nervous truth-tellers and calm liars. The other options contradict 'It does not' or claim the body signals cannot be measured, which the paragraph never says.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-239","question":"Choose the set of words that fills the numbered blanks correctly: Unexpected inflation (1) ___ debtors at the expense of savers. A loan taken when prices were low is (2) ___ in money that buys less, so the real burden of the debt quietly (3) ___.","options":["favours, repaid, grows","punishes, repaid, grows","favours, repaid, shrinks","favours, borrowed, shrinks"],"answer":2,"explanation":"Debtors repay in money that buys less, so inflation 'favours' them, the loan is 'repaid' in cheaper money, and its real burden 'shrinks'. 'Grows' reverses the logic of the second sentence.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-240","question":"Fill in the blank: The clerk's explanation for the missing files, while not strictly impossible, was so ___ that even his supporters found it hard to believe.","options":["far-fetched","watertight","cogent","irrefutable"],"answer":0,"explanation":"Possible in principle but hard to believe means 'far-fetched'. 'Watertight', 'cogent' and 'irrefutable' all mean convincing, the opposite.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-241","question":"Arrange the sentences P, Q, R and S in a logical order to form a coherent paragraph. P: Yet she would be foolish to type her own letters. Q: Suppose a lawyer types faster than any secretary she could hire. R: Every hour spent typing is an hour not spent on legal work that earns her far more. S: What matters, in other words, is not absolute skill but what one gives up.","options":["QRPS","QPRS","PQRS","QPSR"],"answer":1,"explanation":"Q sets up the case; P's 'Yet' gives the surprising conclusion; R justifies it; S generalises ('in other words'). R must follow P because it explains why typing would be foolish.","difficulty":"hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-242","question":"In the sentence below, which word is used INCORRECTLY? The defendant's lawyer tried to elicit sympathy from the jury, but the judge warned him not to flout the rules of procedure, and the principle witness's testimony proved damning.","options":["elicit","flout","principle","damning"],"answer":2,"explanation":"The adjective meaning 'main' is 'principal'; 'principle' is a noun meaning a rule or belief. 'Elicit' (draw out), 'flout' (openly disregard) and 'damning' are used correctly.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-243","question":"Fill in the blank: Far from being a recent invention, the idea that cities should be designed around pedestrians rather than vehicles is a ___: it is how most cities were built before the car arrived.","options":["radical break with the past","return to an older wisdom","product of modern technology","concession to motorists"],"answer":1,"explanation":"'Far from being a recent invention' and 'how most cities were built before the car' show the idea is old, so it is 'a return to an older wisdom'. 'A radical break with the past' is exactly what the sentence denies.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-244","question":"Fill in the blank: He is used to ___ long hours, having worked night shifts for years.","options":["work","to work","worked","working"],"answer":3,"explanation":"In 'be used to' (be accustomed to), 'to' is a preposition and takes a gerund: 'is used to working'. 'Used to work' (without 'is') would mean a past habit.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"eng-cloze-rearrangement-245","question":"Fill in the blanks: His humility was ___; beneath the self-deprecating jokes lay a ___ conviction that he was the cleverest person in any room.","options":["genuine, nagging","studied, serene","studied, wavering","feigned, faint"],"answer":1,"explanation":"'Beneath the jokes' shows the humility was 'studied' (put on), and the hidden belief was firm and untroubled: 'serene'. 'Wavering' and 'faint' weaken the conviction, and 'genuine' contradicts 'beneath'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-246","question":"Arrange the sentences P, Q, R, S and T in a logical order to form a coherent paragraph. P: Some people cannot be vaccinated at all: newborn babies, for example, or patients whose immune systems have been weakened by cancer treatment. Q: A vaccine protects not only the person who receives it. R: Their safety depends on the people around them. S: Each vaccinated person is one fewer link through which a disease can travel. T: When enough links are broken, the disease cannot spread, and people like these are shielded too.","options":["QPRST","QSTPR","QPSTR","PRQST"],"answer":0,"explanation":"Q opens the idea; P introduces those who cannot be vaccinated; R ('Their safety') must follow P; S and T explain the chain, and T's 'people like these' refers back to P. Hence QPRST.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-247","question":"Fill in the blank: The regulator's fine, though large in absolute terms, was ___ for a firm whose profits from the offending practice ran to fifty times the amount.","options":["crippling","exorbitant","a pittance","unprecedented"],"answer":2,"explanation":"'Though large' sets up a contrast: relative to profits fifty times bigger, the fine was trivial, 'a pittance'. 'Crippling' and 'exorbitant' ignore the contrast.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-248","question":"Where does the following sentence best fit in the paragraph? 'But removing them, it turned out, also removed the river's brakes.' (A) For centuries, fallen trees and logjams were cleared from rivers to make way for boats. (B) And for a while, the cleared channels served boatmen well. (C) Without the wood to slow it, water rushed downstream faster, cutting deeper beds and flooding towns below. (D) Some river managers now deliberately place logs back in streams.","options":["After sentence (A)","After sentence (B)","After sentence (C)","After sentence (D)"],"answer":1,"explanation":"'But' turns from the short-lived benefit in (B) to the hidden cost, and 'the river's brakes' is then explained by (C)'s 'Without the wood to slow it'. After (A), (B)'s 'And for a while' would wrongly follow the warning.","difficulty":"very-hard","source":"CAT · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-249","question":"Fill in the blank: The board was ___ in its support for the chief executive until the scandal broke; within a week, half its members had called for her removal.","options":["lukewarm","tentative","half-hearted","unwavering"],"answer":3,"explanation":"'Until the scandal broke' marks a sharp change, so the earlier support must have been firm: 'unwavering'. 'Lukewarm', 'tentative' and 'half-hearted' would make the turn unsurprising.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-cloze-rearrangement-250","question":"Fill in the blank: The project was completed well ___ schedule, saving the company several lakh rupees.","options":["before of","in advance","prior","ahead of"],"answer":3,"explanation":"The idiom is 'ahead of schedule'. 'Prior' would need 'to', 'in advance' would need 'of', and 'before of' is ungrammatical.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO"},
];

export default questions;
